/* Banque de questions supplémentaires : Histoire-Géo-EMC, chapitres 1, 2, 3, 4, h-colonisations, h-didactique, hc4-medieval, hc4-revolutions, hc4-guerres, hc4-depuis1945, gc4-monde, gc4-france, ec4-emc, hc4-methode */
window.BANK = window.BANK || {};
BANK['hgemc/1'] = [
  { q: "Le mot « Paléolithique » signifie :", choices: ["« pierre polie »", "« pierre ancienne »", "« nouvelle pierre »"], answer: 1, expl: "Du grec <i>palaios</i> (ancien) et <i>lithos</i> (pierre) : le <b>Paléolithique</b> est l’âge de la <b>pierre taillée</b>. Le Néolithique (« nouvelle pierre ») est celui de la pierre polie : ne confonds pas les deux préfixes." },
  { q: "Quel système d’écriture utilisaient les Égyptiens de l’Antiquité ?", answers: ["hiéroglyphes", "les hiéroglyphes", "hiéroglyphe", "les hiéroglyphes égyptiens"], expl: "Les Égyptiens écrivaient en <b>hiéroglyphes</b>, des signes-images gravés ou peints. L’écriture <b>cunéiforme</b> (en forme de « clous »), elle, est celle de la Mésopotamie : c’est le piège classique." },
  { q: "Les alignements de menhirs de Carnac (Bretagne) datent :", choices: ["du Paléolithique", "de la Gaule romaine", "du Néolithique", "du Moyen Âge"], answer: 2, expl: "Les <b>mégalithes</b> (menhirs, dolmens) comme ceux de Carnac sont élevés au <b>Néolithique</b>, par des sociétés sédentaires d’agriculteurs capables d’organiser de grands chantiers collectifs." },
  { q: "Dans quelle région du monde apparaissent les premières écritures, vers −3300 ?", answers: ["Mésopotamie", "la Mésopotamie"], expl: "C’est en <b>Mésopotamie</b> (entre le Tigre et l’Euphrate, l’Irak actuel) qu’apparaît l’écriture cunéiforme vers −3300. Cette invention marque le passage de la Préhistoire à l’Antiquité." },
  { q: "Les premiers Jeux olympiques de la Grèce antique datent traditionnellement de :", choices: ["476", "−52", "−776"], answer: 2, expl: "On date les premiers Jeux olympiques de <b>−776</b>, à Olympie, en l’honneur de Zeus. −52, c’est Alésia ; 476, la chute de l’Empire romain d’Occident." },
  { q: "Le pont du Gard est :", choices: ["un pont fortifié du Moyen Âge", "un monument mégalithique", "un aqueduc romain"], answer: 2, expl: "Le pont du Gard est un <b>aqueduc romain</b> du Iᵉʳ siècle qui conduisait l’eau jusqu’à Nîmes. C’est un bel exemple de la <b>romanisation</b> de la Gaule (routes, villes, aqueducs)." },
  { q: "Quel roi des Francs reçoit le baptême vers 496 ?", answers: ["Clovis", "Clovis Iᵉʳ", "Clovis Ier", "Clovis 1er"], expl: "<b>Clovis</b>, roi des Francs, se fait baptiser à Reims vers 496 (ou 498/499). Ce choix du christianisme lui assure le soutien de l’Église et des populations gallo-romaines." },
  { type: 'vf', q: "L’an 2000 appartient au XXIᵉ siècle.", answer: 1, expl: "<b>Faux</b> : le XXᵉ siècle va de <b>1901 à 2000</b> inclus, car le Iᵉʳ siècle commence en l’an 1 (il n’y a pas d’année 0). Le XXIᵉ siècle a donc commencé le 1ᵉʳ janvier <b>2001</b>. Piège très fréquent !" },
  { q: "Dans la formule médiévale « ceux qui prient, ceux qui combattent, ceux qui travaillent », on désigne dans l’ordre :", choices: ["les paysans, la noblesse, le clergé", "la noblesse, le clergé, les paysans", "le roi, les chevaliers, les marchands", "le clergé, la noblesse, les paysans"], answer: 3, expl: "Ceux qui <b>prient</b> = le <b>clergé</b> ; ceux qui <b>combattent</b> = la <b>noblesse</b> (les chevaliers) ; ceux qui <b>travaillent</b> = les <b>paysans</b>, l’immense majorité de la population." },
  { type: 'vf', q: "Le christianisme devient la religion officielle de l’Empire romain au IVᵉ siècle.", answer: 0, expl: "<b>Vrai</b> : d’abord persécuté, le christianisme est autorisé par Constantin (313), puis devient religion officielle sous Théodose (380), donc au <b>IVᵉ siècle</b>." },
  { q: "La première croisade est lancée en :", choices: ["800", "1453", "987", "1095"], answer: 3, expl: "C’est le pape Urbain II qui appelle à la première croisade en <b>1095</b>, au concile de Clermont ; Jérusalem est prise en 1099. 987 = Hugues Capet, 1453 = fin de la guerre de Cent Ans, 800 = Charlemagne." },
  { q: "En quelle année Jeanne d’Arc meurt-elle sur le bûcher, à Rouen ?", answers: ["1431"], expl: "Jeanne d’Arc, capturée par les Bourguignons et livrée aux Anglais, est condamnée et brûlée à Rouen en <b>1431</b>, en pleine guerre de Cent Ans (1337-1453)." },
  { type: 'vf', q: "La guerre de Cent Ans a duré exactement cent ans.", answer: 1, expl: "<b>Faux</b> : elle va de <b>1337 à 1453</b>, soit 1453 − 1337 = <b>116 ans</b>, entrecoupés de trêves. Le nom « Cent Ans » a été donné plus tard par les historiens." },
  { q: "Al-Andalus désigne :", choices: ["la partie de la péninsule Ibérique sous domination musulmane", "une cité grecque d’Asie Mineure", "la capitale du califat abbasside"], answer: 0, expl: "<b>Al-Andalus</b> est le nom de l’Espagne (et du Portugal) musulmane au Moyen Âge, avec Cordoue pour grande capitale. La capitale abbasside, c’est Bagdad." },
  { q: "Quelle grotte ornée d’Ardèche, datée d’environ −36 000, contient parmi les plus anciennes peintures connues ?", answers: ["Chauvet", "grotte Chauvet", "la grotte Chauvet", "Chauvet-Pont-d’Arc", "grotte Chauvet-Pont-d’Arc"], expl: "La grotte <b>Chauvet</b> (≈ −36 000) est bien plus ancienne que <b>Lascaux</b> (≈ −18 000) : les deux datent pourtant du <b>Paléolithique</b>. Retiens l’ordre : Chauvet avant Lascaux." },
  { q: "Combien d’années séparent le couronnement de Charlemagne (800) et l’élection d’Hugues Capet (987) ?", answers: ["187", "187 ans"], expl: "Pour une durée entre deux dates après J.-C., on soustrait : 987 − 800 = <b>187 ans</b>. Attention, si l’une des dates est avant J.-C., il faut tenir compte de l’absence d’année 0." },
  { type: 'vf', q: "Entre l’an −10 et l’an 10, il s’est écoulé 20 ans.", answer: 1, expl: "<b>Faux</b> : il n’y a <b>pas d’année 0</b>. On passe directement de l’an −1 à l’an 1. De −10 à 10, il s’écoule donc 10 + 10 − 1 = <b>19 ans</b>. C’est un piège classique de calcul de durée." },
  { q: "Un élève écrit que 1492 se situe au XIVᵉ siècle. Quelle est son erreur ?", choices: ["Il a confondu 1492 avec 1453", "Il n’y a pas d’erreur : 1492 est bien au XIVᵉ siècle", "Il a pris les deux premiers chiffres (14) sans ajouter 1 : c’est le XVᵉ siècle"], answer: 2, expl: "Le XVᵉ siècle va de 1401 à 1500 : pour 1492, on prend les centaines (14) et on <b>ajoute 1</b> → <b>XVᵉ siècle</b>. L’élève a oublié ce « +1 », l’erreur la plus fréquente sur les siècles." },
  { q: "<i>La Guerre des Gaules</i> est un récit écrit par Jules César lui-même. Quelle est sa principale limite pour l’historien ?", choices: ["C’est un texte de fiction sans lien avec des faits réels", "C’est une source secondaire écrite des siècles plus tard", "C’est le point de vue du vainqueur, qui cherche à se mettre en valeur"], answer: 2, expl: "Ce texte est une <b>source primaire</b> précieuse, mais il est écrit par le <b>vainqueur</b>, qui veut justifier sa conquête et valoriser ses exploits à Rome. Il faut le croiser avec d’autres sources (archéologie d’Alésia, par exemple)." },
  { q: "Laquelle de ces innovations n’apparaît PAS au Néolithique ?", choices: ["la poterie", "l’écriture", "l’agriculture", "l’élevage"], answer: 1, expl: "Agriculture, élevage, poterie, pierre polie et villages sont des innovations du <b>Néolithique</b>. L’<b>écriture</b>, vers −3300, marque justement la <b>fin</b> de la Préhistoire et le début de l’Antiquité." }
];
BANK['hgemc/2'] = [
  { q: "Quelle invention du milieu du XVᵉ siècle favorise la diffusion des idées humanistes ?", choices: ["l’imprimerie à caractères mobiles", "le télégraphe", "la machine à vapeur"], answer: 0, expl: "L’<b>imprimerie</b> de Gutenberg (vers 1450) permet de reproduire les livres plus vite et moins cher : les textes des humanistes circulent dans toute l’Europe. La machine à vapeur et le télégraphe datent des XVIIIᵉ-XIXᵉ siècles." },
  { q: "Quel roi de France remporte la bataille de Marignan en 1515 ?", answers: ["François Iᵉʳ", "François Ier", "François 1er", "François I", "François premier"], expl: "C’est <b>François Iᵉʳ</b>, roi de la Renaissance, qui gagne à Marignan en <b>1515</b>, en Italie. C’est aussi lui qui signe l’ordonnance de Villers-Cotterêts en 1539." },
  { q: "L’ordonnance de Villers-Cotterêts (1539) :", choices: ["rend l’école primaire obligatoire", "accorde la liberté de culte aux protestants", "impose le français dans les actes officiels et de justice"], answer: 2, expl: "Par cette ordonnance, <b>François Iᵉʳ</b> impose le <b>français</b> à la place du latin dans les actes officiels. La liberté de culte aux protestants, c’est l’édit de Nantes (1598), et l’école obligatoire, les lois Ferry (1882)." },
  { q: "Quel roi signe l’édit de Nantes en 1598 ?", choices: ["Louis XIV", "Henri IV", "Louis XVI", "François Iᵉʳ"], answer: 1, expl: "C’est <b>Henri IV</b>, ancien protestant converti au catholicisme, qui signe l’édit de Nantes pour mettre fin aux guerres de Religion. Louis XIV le révoquera en 1685 : ne confonds pas les deux rois." },
  { type: 'vf', q: "Louis XIV a régné de 1643 à 1715, soit plus de 70 ans.", answer: 0, expl: "<b>Vrai</b> : 1715 − 1643 = <b>72 ans</b>, l’un des plus longs règnes de l’histoire de France. Devenu roi à 4 ans, il ne gouverne personnellement qu’à partir de 1661." },
  { q: "Qui dirige l’<i>Encyclopédie</i> avec d’Alembert ?", choices: ["Diderot", "Montesquieu", "Rousseau", "Voltaire"], answer: 0, expl: "<b>Denis Diderot</b> dirige l’<i>Encyclopédie</i> avec d’Alembert (à partir de 1751) : cette œuvre collective veut rassembler et diffuser les connaissances, dans l’esprit des Lumières." },
  { q: "Range ces événements de 1789 dans l’ordre chronologique :", choices: ["abolition des privilèges → prise de la Bastille → DDHC", "prise de la Bastille → abolition des privilèges → DDHC", "DDHC → prise de la Bastille → abolition des privilèges"], answer: 1, expl: "<b>14 juillet</b> : prise de la Bastille ; <b>4 août</b> : abolition des privilèges ; <b>26 août</b> : Déclaration des droits de l’homme et du citoyen. Tout se passe en un peu plus d’un mois !" },
  { q: "En quelle année Louis XVI est-il exécuté ?", answers: ["1793"], expl: "Louis XVI est guillotiné le 21 janvier <b>1793</b>, quelques mois après la proclamation de la République (septembre 1792). Ne confonds pas avec 1792 : la République vient d’abord, l’exécution ensuite." },
  { type: 'vf', q: "L’esclavage, aboli une première fois en 1794, a été rétabli par Napoléon Bonaparte en 1802.", answer: 0, expl: "<b>Vrai</b> : la Convention abolit l’esclavage en <b>1794</b>, Bonaparte le rétablit en <b>1802</b>, et il faut attendre <b>1848</b> pour l’abolition définitive. Trois dates à bien retenir ensemble." },
  { q: "Napoléon Bonaparte est sacré empereur en :", choices: ["1799", "1792", "1815", "1804"], answer: 3, expl: "Le sacre a lieu à Notre-Dame de Paris le 2 décembre <b>1804</b>, la même année que le Code civil. 1799 est son coup d’État, 1815 sa défaite à Waterloo." },
  { q: "En quelle année le suffrage universel masculin est-il instauré en France ?", answers: ["1848"], expl: "Le suffrage universel <b>masculin</b> est instauré en <b>1848</b> par la IIᵉ République, la même année que l’abolition définitive de l’esclavage. Les femmes devront attendre 1944." },
  { q: "Quelle source d’énergie est au cœur de la révolution industrielle du XIXᵉ siècle ?", choices: ["le charbon", "l’énergie nucléaire", "le pétrole"], answer: 0, expl: "Le <b>charbon</b> alimente les machines à vapeur des usines, des locomotives et des bateaux. Le pétrole ne s’impose qu’à la fin du XIXᵉ et surtout au XXᵉ siècle, et le nucléaire après 1945." },
  { q: "L’exode rural désigne :", choices: ["le départ des citadins vers la campagne", "l’émigration des Européens vers l’Amérique", "le départ massif des habitants des campagnes vers les villes"], answer: 2, expl: "Avec l’industrialisation, les paysans quittent les campagnes pour trouver du travail dans les usines des villes : c’est l’<b>exode rural</b>. Le mouvement inverse, récent, s’appelle la périurbanisation ou le retour à la campagne." },
  { type: 'vf', q: "Les lois Ferry rendent l’école obligatoire de 6 à 16 ans.", answer: 1, expl: "<b>Faux</b> : les lois Ferry (1882) rendent l’instruction obligatoire de <b>6 à 13 ans</b>. Elle sera prolongée jusqu’à 16 ans en 1959, et aujourd’hui elle commence dès 3 ans (2019)." },
  { q: "Quelle bataille de 1916, symbole de la Grande Guerre pour les Français, dure près de 10 mois ?", answers: ["Verdun", "la bataille de Verdun", "bataille de Verdun"], expl: "La bataille de <b>Verdun</b> (février-décembre 1916) fait environ 300 000 morts français et allemands : elle symbolise l’horreur de la guerre des tranchées." },
  { q: "Le débarquement allié en Normandie a lieu le :", choices: ["6 juin 1944", "8 mai 1945", "11 novembre 1918"], answer: 0, expl: "Le <b>6 juin 1944</b> (le « D-Day »), les Alliés débarquent sur les plages de Normandie : c’est le début de la libération de la France. Le 8 mai 1945, c’est la capitulation allemande." },
  { q: "Combien de pays fondent la CEE par le traité de Rome en 1957 ?", answers: ["6", "six"], expl: "La CEE naît à <b>6</b> : France, RFA (Allemagne de l’Ouest), Italie, Belgique, Pays-Bas et Luxembourg. Elle s’élargit ensuite jusqu’aux 27 États de l’Union européenne actuelle." },
  { q: "Les pièces et billets en euros sont mis en circulation en :", choices: ["1992", "1957", "2002"], answer: 2, expl: "L’euro est créé comme monnaie de compte en 1999, mais les <b>pièces et billets</b> circulent à partir du 1ᵉʳ janvier <b>2002</b>. 1992 est la date du traité de Maastricht qui l’a prévu." },
  { type: 'vf', q: "L’Algérie devient indépendante en 1962, sous la Vᵉ République.", answer: 0, expl: "<b>Vrai</b> : la Vᵉ République est fondée en <b>1958</b>, en pleine guerre d’Algérie ; l’indépendance est obtenue en <b>1962</b> après les accords d’Évian, sous la présidence du général de Gaulle." },
  { q: "Sur une frise qui commence en 1700, avec 1 cm pour 10 ans, à combien de centimètres de l’origine places-tu l’année 1789 ? (en cm)", answers: ["8,9", "8.9", "8,9 cm", "8.9 cm"], expl: "Durée depuis l’origine : 1789 − 1700 = 89 ans. Avec 1 cm pour 10 ans : 89 ÷ 10 = <b>8,9 cm</b>. On calcule toujours une <b>durée</b> avant de convertir en longueur." }
];
BANK['hgemc/3'] = [
  { q: "Combien la France compte-t-elle de régions en métropole ?", choices: ["13", "101", "18", "22"], answer: 0, expl: "Depuis la réforme de 2016, la France métropolitaine compte <b>13 régions</b> (Corse comprise), et 18 en ajoutant les 5 régions d’outre-mer. 22 était l’ancien nombre ; 101, c’est celui des départements." },
  { q: "Combien d’océans compte-t-on sur la Terre ?", answers: ["5", "cinq"], expl: "On compte <b>5 océans</b> : Pacifique, Atlantique, Indien, Arctique et Austral (autour de l’Antarctique). Ne les confonds pas avec les 6 continents." },
  { type: 'vf', q: "Le tropique du Cancer est situé dans l’hémisphère Sud.", answer: 1, expl: "<b>Faux</b> : le tropique du <b>Cancer</b> est dans l’hémisphère <b>Nord</b> (il passe par le Sahara, l’Inde, le Mexique) ; le tropique du <b>Capricorne</b> est dans l’hémisphère Sud." },
  { q: "Les Pyrénées forment une frontière naturelle entre la France et :", choices: ["l’Italie", "l’Allemagne", "l’Espagne", "la Suisse"], answer: 2, expl: "Les <b>Pyrénées</b> séparent la France de l’<b>Espagne</b> (et d’Andorre). Les Alpes nous séparent de l’Italie et de la Suisse, le Rhin de l’Allemagne." },
  { q: "Sur une carte au 1/25 000, combien de kilomètres représentent 4 cm ?", answers: ["1", "1 km"], expl: "4 cm × 25 000 = 100 000 cm. Or 100 000 cm = 1 000 m = <b>1 km</b>. Méthode : multiplier par le dénominateur de l’échelle, puis convertir les centimètres en kilomètres." },
  { q: "Sur une carte au 1/50 000, quelle longueur (en cm) représente une distance réelle de 15 km ?", answers: ["30", "30 cm"], expl: "15 km = 1 500 000 cm. On divise par 50 000 : 1 500 000 ÷ 50 000 = <b>30 cm</b>. Le piège : oublier de convertir les km en cm avant de diviser." },
  { q: "Sur un croquis, un axe autoroutier est représenté par un figuré :", choices: ["linéaire", "surfacique", "ponctuel"], answer: 0, expl: "Une route, un fleuve, une frontière ou un flux se représentent par un figuré <b>linéaire</b> (trait, flèche). Le ponctuel sert aux villes ou aux ports, le surfacique aux zones." },
  { q: "Quel DROM est situé en Amérique du Sud ?", answers: ["Guyane", "la Guyane", "Guyane française"], expl: "La <b>Guyane</b> est le seul DROM situé sur un continent, en Amérique du Sud, entre le Suriname et le Brésil. La Guadeloupe et la Martinique sont des îles des Antilles." },
  { q: "Lequel de ces DROM se trouve dans l’océan Indien ?", choices: ["la Martinique", "La Réunion", "la Guyane", "la Guadeloupe"], answer: 1, expl: "<b>La Réunion</b> (et Mayotte) se trouvent dans l’océan <b>Indien</b>. Martinique et Guadeloupe sont dans la mer des Caraïbes (océan Atlantique), la Guyane en Amérique du Sud." },
  { type: 'vf', q: "Aujourd’hui, plus de la moitié de la population mondiale vit en ville.", answer: 0, expl: "<b>Vrai</b> : depuis 2007 environ, les citadins sont majoritaires, et la part de la population urbaine continue d’augmenter. C’est l’un des grands changements de notre époque." },
  { q: "Où se situent les principaux foyers de peuplement de la planète ?", choices: ["en Sibérie et au Canada", "en Asie de l’Est et en Asie du Sud", "en Amazonie et au Sahara"], answer: 1, expl: "Les grands foyers de peuplement sont l’<b>Asie de l’Est</b> (Chine), l’<b>Asie du Sud</b> (Inde) et l’<b>Europe</b>. L’Amazonie, le Sahara, la Sibérie sont au contraire des espaces presque vides." },
  { q: "Quel rapport de 1987 a popularisé la définition du développement durable ?", answers: ["Brundtland", "rapport Brundtland", "le rapport Brundtland"], expl: "Le rapport <b>Brundtland</b> (1987, du nom de la Première ministre norvégienne qui présidait la commission de l’ONU) définit le développement durable comme un développement qui répond aux besoins du présent sans compromettre ceux des générations futures." },
  { q: "Combien d’Objectifs de développement durable (ODD) l’ONU a-t-elle fixés ?", choices: ["27", "17", "8", "3"], answer: 1, expl: "L’ONU a adopté en 2015 <b>17 ODD</b> à atteindre d’ici 2030 (faim, eau, éducation, climat…). Ne confonds pas avec les <b>3 piliers</b> du développement durable." },
  { type: 'vf', q: "La Garonne se jette dans la mer Méditerranée.", answer: 1, expl: "<b>Faux</b> : la Garonne rejoint la Dordogne pour former l’estuaire de la <b>Gironde</b>, qui se jette dans l’océan <b>Atlantique</b>. C’est le <b>Rhône</b> qui se jette dans la Méditerranée." },
  { q: "Au cycle 3, le thème « habiter un espace à fortes contraintes » peut s’appuyer sur l’étude :", choices: ["d’un désert ou d’une haute montagne", "d’un centre commercial de la ville", "du quartier de l’école"], answer: 0, expl: "Un espace à <b>fortes contraintes</b> est difficile à habiter (aridité, froid, altitude, relief) : désert, haute montagne, région polaire. Le quartier de l’école relève du thème « découvrir les lieux où j’habite »." },
  { q: "Le porte-conteneurs est souvent choisi comme symbole :", choices: ["de la mondialisation des échanges de marchandises", "du développement durable", "de la métropolisation"], answer: 0, expl: "Le <b>conteneur</b>, boîte standardisée transportée par d’immenses navires, a fait baisser le coût du transport : il symbolise la <b>mondialisation</b> des échanges de marchandises." },
  { type: 'vf', q: "Le Rhin marque une partie de la frontière entre la France et l’Allemagne.", answer: 0, expl: "<b>Vrai</b> : en Alsace, le <b>Rhin</b> sert de frontière avec l’Allemagne. C’est un grand fleuve européen, long d’environ 1 230 km, dont une petite partie seulement concerne la France." },
  { q: "Quelle est la population approximative de la France ?", choices: ["68 millions d’habitants", "48 millions d’habitants", "88 millions d’habitants"], answer: 0, expl: "La France compte environ <b>68 millions</b> d’habitants (outre-mer compris). C’est le 2ᵉ pays le plus peuplé de l’Union européenne, après l’Allemagne (environ 84 millions)." },
  { q: "Quel massif montagneux, à la frontière franco-suisse, a donné son nom à une période géologique ?", answers: ["Jura", "le Jura"], expl: "Le <b>Jura</b> s’étend entre la France et la Suisse ; il a donné son nom au <b>Jurassique</b>. Les autres massifs : Alpes, Pyrénées, Massif central, Vosges." },
  { type: 'vf', q: "Sur toute carte, le nord est obligatoirement placé en haut.", answer: 1, expl: "<b>Faux</b> : c’est une convention fréquente, mais pas une règle. C’est pour cela qu’une carte doit toujours comporter une <b>orientation</b> (une flèche indiquant le nord). C’est une idée fausse répandue chez les élèves." }
];
BANK['hgemc/4'] = [
  { q: "Complète l’article 1ᵉʳ de la Constitution : « La France est une République indivisible, laïque, démocratique et … »", answers: ["sociale"], expl: "« La France est une République indivisible, laïque, démocratique et <b>sociale</b>. » « Sociale » signifie que la République veille à la solidarité (protection sociale, égalité des chances)." },
  { q: "Qui a composé <i>La Marseillaise</i> en 1792 ?", choices: ["Victor Hugo", "Rouget de Lisle", "Napoléon Bonaparte", "Robespierre"], answer: 1, expl: "<b>Rouget de Lisle</b>, officier du génie, compose ce chant à Strasbourg en 1792 pour l’armée du Rhin. Il prend le nom de <i>Marseillaise</i> car il est chanté par les fédérés marseillais montant à Paris." },
  { q: "Lequel de ces symboles n’a pas de statut officiel ?", choices: ["le drapeau tricolore", "Marianne", "le coq", "la devise « Liberté, Égalité, Fraternité »"], answer: 2, expl: "Le <b>coq</b> est un symbole <b>officieux</b> (on le voit surtout dans le sport). Le drapeau, l’hymne, la devise sont inscrits dans la Constitution, et Marianne figure sur les timbres, les pièces et le logo officiel de l’État." },
  { q: "Combien d’articles compte la Charte de la laïcité à l’École ?", answers: ["15", "quinze"], expl: "La Charte de la laïcité à l’École compte <b>15 articles</b>. Elle doit être affichée dans tous les établissements publics et peut servir de support en EMC." },
  { q: "En quelle année la Charte de la laïcité à l’École a-t-elle été publiée ?", answers: ["2013"], expl: "La Charte date de <b>2013</b>. Ne la confonds pas avec la loi de <b>2004</b> (signes religieux ostensibles) ni avec la loi de <b>1905</b> (séparation des Églises et de l’État)." },
  { type: 'vf', q: "La laïcité interdit aux élèves d’avoir une religion.", answer: 1, expl: "<b>Faux</b> : la laïcité garantit au contraire la <b>liberté de conscience</b> : chacun peut croire ou ne pas croire. À l’école, elle impose la neutralité des personnels et interdit seulement aux élèves les signes religieux <b>ostensibles</b>." },
  { type: 'vf', q: "Un élève d’une école publique peut porter une petite médaille religieuse discrète.", answer: 0, expl: "<b>Vrai</b> : la loi de 2004 interdit les signes <b>ostensibles</b> (qui manifestent ostensiblement une appartenance religieuse), pas les signes <b>discrets</b>. Attention : pour l’<b>enseignant</b>, c’est différent, il ne peut porter aucun signe." },
  { q: "Les sénateurs sont élus :", choices: ["par le Président de la République", "au suffrage universel indirect, par des grands électeurs", "au suffrage universel direct, par tous les citoyens"], answer: 1, expl: "Les sénateurs sont élus au suffrage universel <b>indirect</b> par des <b>grands électeurs</b> (surtout des élus locaux). Les députés, eux, sont élus au suffrage universel <b>direct</b>." },
  { q: "Sous la Vᵉ République, le Premier ministre est :", choices: ["élu directement par les citoyens", "nommé par le Président de la République", "élu par le Sénat"], answer: 1, expl: "Le Premier ministre est <b>nommé</b> par le Président (article 8 de la Constitution). Il dirige le gouvernement, qui est responsable devant l’Assemblée nationale." },
  { q: "Qui dirige la commune, avec le conseil municipal ?", answers: ["maire", "le maire"], expl: "Le <b>maire</b> est élu par le conseil municipal, lui-même élu par les habitants. Il est à la fois agent de l’État (état civil) et chef de l’exécutif communal." },
  { q: "Un citoyen d’un autre pays de l’Union européenne qui réside en France peut voter :", choices: ["aux élections municipales et européennes", "aux élections législatives", "à l’élection présidentielle"], answer: 0, expl: "La citoyenneté européenne (traité de Maastricht) permet de voter aux élections <b>municipales</b> et <b>européennes</b> dans son pays de résidence. La présidentielle et les législatives restent réservées aux Français." },
  { type: 'vf', q: "Le Président de la République fait partie du pouvoir législatif.", answer: 1, expl: "<b>Faux</b> : le Président appartient au pouvoir <b>exécutif</b>, avec le gouvernement. Le pouvoir législatif, c’est le <b>Parlement</b> (Assemblée nationale et Sénat), qui vote les lois." },
  { q: "Parmi ces droits, lequel figure dans la Convention internationale des droits de l’enfant ?", choices: ["le droit de ne pas aller à l’école", "le droit de voter dès 12 ans", "le droit d’exprimer son opinion sur les questions qui le concernent"], answer: 2, expl: "La CIDE reconnaît le droit de l’enfant à <b>exprimer librement son opinion</b> (article 12), ainsi que le droit à l’éducation, à la santé, à la protection. Le droit de vote, lui, est réservé aux majeurs." },
  { q: "Quel est le nom du programme national de lutte contre le harcèlement à l’école ?", answers: ["pHARe", "phare", "programme pHARe", "le programme pHARe"], expl: "Le programme <b>pHARe</b> (avec « HAR » pour harcèlement) organise la prévention dans les écoles et collèges : formation des adultes, élèves ambassadeurs, heures dédiées à l’empathie." },
  { q: "Laquelle de ces questions est la plus adaptée à une discussion à visée philosophique ?", choices: ["En quelle année a été votée la loi de 1905 ?", "Peut-on être libre tout seul ?", "Combien y a-t-il de députés ?"], answer: 1, expl: "Une DVP porte sur une <b>notion</b> (liberté, justice, amitié) et sur une question <b>ouverte</b>, sans réponse unique. Les deux autres questions sont fermées : elles relèvent de la connaissance, pas de la réflexion." },
  { q: "Dans un débat réglé, le rôle principal de l’enseignant est de :", choices: ["noter les élèves qui parlent le plus", "garantir le cadre et les règles, et aider à faire émerger les arguments", "donner son opinion personnelle pour conclure"], answer: 1, expl: "L’enseignant <b>garantit le cadre</b> (règles de parole, respect) et aide les élèves à <b>argumenter</b> et à reformuler. Il reste neutre sur les opinions et ne récompense pas la quantité de parole." },
  { type: 'vf', q: "La laïcité garantit la liberté de conscience, c’est-à-dire le droit de croire ou de ne pas croire.", answer: 0, expl: "<b>Vrai</b> : c’est le cœur de la laïcité (article 1ᵉʳ de la loi de 1905). L’État est neutre pour que chacun soit libre de ses convictions, religieuses ou non." },
  { q: "Pour combien d’années les députés sont-ils élus ?", answers: ["5", "5 ans", "cinq ans", "cinq"], expl: "Les 577 députés sont élus pour <b>5 ans</b> au suffrage universel direct, sauf si le Président dissout l’Assemblée avant la fin du mandat. Les sénateurs, eux, sont élus pour 6 ans." },
  { q: "Le conseil d’élèves (ou conseil de coopération) sert surtout à :", choices: ["punir les élèves qui ont désobéi", "réguler la vie de la classe et décider de projets communs", "remplacer les leçons d’EMC par des jeux"], answer: 1, expl: "Le conseil permet aux élèves de <b>débattre des règles</b>, de régler des conflits par la parole et de <b>proposer des projets</b> : c’est un apprentissage concret de la démocratie et de l’engagement." },
  { q: "Selon la Charte de la laïcité à l’École, un élève peut-il refuser un enseignement du programme au nom de ses convictions religieuses ?", choices: ["Oui, sur simple demande écrite des parents", "Non, aucun élève ne peut contester un enseignement du programme pour ce motif", "Oui, mais seulement en sciences"], answer: 1, expl: "<b>Non</b> : l’article 12 de la Charte précise qu’aucun élève ne peut invoquer une conviction religieuse ou politique pour <b>contester</b> le droit de l’enseignant de traiter une question au programme. Les enseignements sont les mêmes pour tous." }
];
BANK['hgemc/h-colonisations'] = [
  { q: "Quel était le premier port négrier français au XVIIIᵉ siècle ?", choices: ["Lille", "Lyon", "Nantes", "Strasbourg"], answer: 2, expl: "<b>Nantes</b> a organisé à elle seule plus de 40 % des expéditions négrières françaises, devant Bordeaux, La Rochelle et Le Havre. Strasbourg, Lyon et Lille ne sont pas des ports de l’Atlantique." },
  { q: "Environ combien de millions d’Africains ont été déportés par la traite atlantique ? (en millions)", answers: ["12", "12 millions", "plus de 12 millions"], expl: "On estime à <b>plus de 12 millions</b> le nombre de captifs africains embarqués vers les Amériques entre le XVIᵉ et le XIXᵉ siècle ; beaucoup sont morts pendant la traversée." },
  { q: "Dans quel type de grandes exploitations agricoles les esclaves étaient-ils contraints de travailler en Amérique ?", answers: ["plantations", "plantation", "les plantations", "des plantations"], expl: "Les esclaves travaillaient de force dans les <b>plantations</b> de canne à sucre, de coton, de café ou de tabac, dont les produits étaient vendus en Europe." },
  { q: "Quel ancien esclave dirige la révolte de Saint-Domingue à la fin du XVIIIᵉ siècle ?", answers: ["Toussaint Louverture", "Toussaint-Louverture", "Louverture", "Toussaint L’Ouverture"], expl: "<b>Toussaint Louverture</b> mène la révolte des esclaves de Saint-Domingue. Arrêté sur ordre de Bonaparte, il meurt en France en 1803 ; l’indépendance d’Haïti est proclamée en 1804 par Dessalines." },
  { q: "La première abolition de l’esclavage (1794) est votée par :", choices: ["Napoléon Bonaparte", "Louis XIV", "la Convention"], answer: 2, expl: "C’est la <b>Convention</b>, assemblée de la Iʳᵉ République, qui abolit l’esclavage le 4 février <b>1794</b>. Louis XIV avait promulgué le Code noir et Napoléon a <b>rétabli</b> l’esclavage en 1802." },
  { type: 'vf', q: "Napoléon Bonaparte a rétabli l’esclavage dans les colonies françaises en 1802.", answer: 0, expl: "<b>Vrai</b> : en <b>1802</b>, Bonaparte rétablit l’esclavage aboli en 1794. Il faudra attendre <b>1848</b> pour l’abolition définitive. C’est un exemple de recul des acquis révolutionnaires." },
  { q: "Combien d’années séparent la première abolition de l’esclavage (1794) de l’abolition définitive (1848) ?", answers: ["54", "54 ans"], expl: "1848 − 1794 = <b>54 ans</b>. Entre les deux, l’esclavage a été rétabli en 1802 : il a donc fallu plus d’un demi-siècle pour une abolition durable." },
  { q: "L’abolition définitive de l’esclavage (1848) a lieu sous :", choices: ["la IIᵉ République", "la Iʳᵉ République", "le Second Empire", "la IIIᵉ République"], answer: 0, expl: "Le décret d’abolition est signé le 27 avril <b>1848</b> par le gouvernement provisoire de la <b>IIᵉ République</b>, à l’initiative de Victor Schœlcher. La IIIᵉ République ne commence qu’en 1870." },
  { q: "Le sigle AOF signifie :", choices: ["Association des outre-mer français", "Afrique orientale fédérale", "Afrique-Occidentale française"], answer: 2, expl: "L’<b>AOF</b> (Afrique-Occidentale française, 1895) regroupait les colonies françaises d’Afrique de l’Ouest (Sénégal, Soudan français, Côte d’Ivoire…). L’AEF était l’Afrique-Équatoriale française." },
  { q: "À la fin du XIXᵉ siècle, la colonisation est justifiée par ses partisans au nom :", choices: ["de la laïcité", "du droit des peuples à disposer d’eux-mêmes", "d’une prétendue « mission civilisatrice »"], answer: 2, expl: "Les partisans de la colonisation (comme Jules Ferry) invoquent une « <b>mission civilisatrice</b> » fondée sur l’idée raciste d’une supériorité européenne. Le droit des peuples à disposer d’eux-mêmes sera au contraire l’argument des indépendances." },
  { q: "Quel ensemble de règles instaure une inégalité de droits entre colons et colonisés dans les colonies françaises ?", answers: ["code de l’indigénat", "indigénat", "l’indigénat", "le code de l’indigénat", "code de l'indigénat"], expl: "Le <b>code de l’indigénat</b> (1881 en Algérie, étendu ensuite) soumet les colonisés, appelés « indigènes », à des sanctions spéciales et au travail forcé, sans les droits des citoyens." },
  { q: "L’Exposition coloniale, qui célèbre l’empire à son apogée, a lieu à Paris en :", choices: ["1962", "1889", "1931"], answer: 2, expl: "L’Exposition coloniale de <b>1931</b>, au bois de Vincennes, montre l’empire à son <b>apogée</b> dans l’entre-deux-guerres. 1889 est l’Exposition universelle de la tour Eiffel ; 1962, l’indépendance de l’Algérie." },
  { q: "Quelle bataille de 1954 marque la défaite française en Indochine ?", answers: ["Diên Biên Phu", "Dien Bien Phu", "Diên Biên Phú", "Dien-Bien-Phu"], expl: "À <b>Diên Biên Phu</b> (mai 1954), l’armée française est vaincue par le Viêt-minh. Les accords de Genève (1954) mettent fin à la guerre d’Indochine. La même année commence la guerre d’Algérie." },
  { q: "Quels accords mettent fin à la guerre d’Algérie en 1962 ?", choices: ["les accords d’Évian", "le traité de Versailles", "les accords de Genève", "le traité de Rome"], answer: 0, expl: "Les <b>accords d’Évian</b> (mars 1962) organisent le cessez-le-feu et le référendum d’autodétermination : l’Algérie devient indépendante en juillet 1962. Les accords de Genève (1954) concernent l’Indochine." },
  { type: 'vf', q: "La guerre d’Algérie commence en 1954 et dure environ huit ans.", answer: 0, expl: "<b>Vrai</b> : elle débute le 1ᵉʳ novembre <b>1954</b> (« Toussaint rouge ») et se termine en <b>1962</b>, soit environ <b>8 ans</b> de conflit." },
  { type: 'vf', q: "L’empire colonial français atteint son apogée juste avant la Révolution française.", answer: 1, expl: "<b>Faux</b> : l’empire atteint sa plus grande extension dans l’<b>entre-deux-guerres</b> (années 1920-1930). Au XVIIIᵉ siècle, la France avait perdu une grande partie de son premier empire (Canada, Inde) en 1763." },
  { type: 'vf', q: "La loi Taubira de 2001 demande que la traite et l’esclavage aient une place dans les programmes scolaires.", answer: 0, expl: "<b>Vrai</b> : en plus de reconnaître la traite et l’esclavage comme crimes contre l’humanité, la loi Taubira demande que les programmes scolaires leur accordent <b>la place conséquente qu’ils méritent</b>." },
  { q: "Pour aborder la traite atlantique avec des élèves de CM2, quelle démarche est la plus adaptée ?", choices: ["croiser des sources variées (gravure, extrait de registre de navire, témoignage) en les contextualisant", "montrer uniquement des images très choquantes pour provoquer l’émotion", "éviter le sujet car il est trop sensible"], answer: 0, expl: "Ce sujet est au programme : on le traite avec des <b>sources variées</b>, présentées et <b>contextualisées</b>, pour construire une connaissance historique. L’émotion seule ne suffit pas, et éviter le sujet n’est pas une option." },
  { q: "Quelle colonie française se trouvait en Asie ?", choices: ["l’Indochine", "le Sénégal", "l’Algérie", "Madagascar"], answer: 0, expl: "L’<b>Indochine</b> française (Vietnam, Laos, Cambodge actuels) était en Asie du Sud-Est. L’Algérie et le Sénégal sont en Afrique, Madagascar est une île africaine de l’océan Indien." },
  { q: "Une affiche de l’Exposition coloniale de 1931 montre des colonisés souriants autour d’un drapeau français. Comment l’analyser ?", choices: ["comme une source secondaire écrite par un historien", "comme une propagande qui veut valoriser l’empire", "comme un témoignage objectif sur la vie dans les colonies"], answer: 1, expl: "Cette affiche est une source <b>primaire</b> produite pour <b>convaincre</b> le public des bienfaits de la colonisation : c’est de la <b>propagande</b>. Elle renseigne sur l’image que l’État voulait donner, pas sur la réalité vécue par les colonisés." }
];
BANK['hgemc/h-didactique'] = [
  { q: "Sur une frise où 1 cm représente 100 ans, quelle longueur (en cm) faut-il pour représenter le Moyen Âge, de 476 à 1492 ?", answers: ["10,16", "10.16", "10,16 cm", "10.16 cm"], expl: "Durée : 1492 − 476 = 1016 ans. Avec 1 cm pour 100 ans : 1016 ÷ 100 = <b>10,16 cm</b>. On calcule d’abord la durée, puis on applique l’échelle de la frise." },
  { q: "Sur une frise où 2 cm représentent un siècle, quelle longueur (en cm) occupe la période 1789-2019 ?", answers: ["4,6", "4.6", "4,6 cm", "4.6 cm"], expl: "Durée : 2019 − 1789 = 230 ans, soit 2,3 siècles. 2,3 × 2 cm = <b>4,6 cm</b>. Le piège : oublier que l’échelle est de 2 cm (et non 1 cm) par siècle." },
  { q: "Un élève de CM1 affirme que la Préhistoire est une période courte, car elle occupe une petite case dans son manuel. Quel est le problème ?", choices: ["la frise du manuel n’est pas à l’échelle : il confond place sur la page et durée réelle", "il confond source primaire et source secondaire", "il ne sait pas lire un paysage"], answer: 0, expl: "La Préhistoire dure des <b>millions d’années</b>, bien plus que toutes les autres périodes réunies. Une frise non proportionnelle trompe l’élève : une frise <b>à l’échelle</b> (même durée = même longueur) l’aide à corriger cette représentation." },
  { q: "En maternelle (cycle 1), le travail sur le temps passe surtout par :", choices: ["la frise des grandes périodes historiques", "la mémorisation des dates des guerres", "les rituels (calendrier, succession des moments de la journée)"], answer: 2, expl: "Au cycle 1, on construit le <b>temps vécu</b> : rituels du calendrier, succession des moments de la journée, avant/après. Les grandes périodes historiques ne sont abordées qu’au <b>cycle 3</b>." },
  { type: 'vf', q: "Au cycle 2, l’arbre généalogique permet d’aborder la notion de générations.", answer: 0, expl: "<b>Vrai</b> : l’arbre généalogique (parents, grands-parents, arrière-grands-parents) fait comprendre la succession des <b>générations</b> et prépare le passage du temps vécu au temps historique." },
  { q: "Dans la méthode « Qui ? Quand ? Quoi ? Pourquoi ? », la question « Pourquoi ? » renvoie à :", choices: ["la date du document", "la nature du document (texte, image…)", "l’intention de l’auteur et au destinataire"], answer: 2, expl: "« <b>Pourquoi ?</b> » interroge l’<b>intention</b> (informer, convaincre, glorifier ?) et le <b>destinataire</b>. La date répond à « Quand ? », la nature et le contenu à « Quoi ? »." },
  { type: 'vf', q: "Une enluminure montrant des paysans heureux au travail prouve que la vie paysanne au Moyen Âge était facile.", answer: 1, expl: "<b>Faux</b> : l’enluminure reflète le regard de ceux qui l’ont <b>commandée</b> (souvent un seigneur ou l’Église), pas forcément la réalité. Il faut la croiser avec d’autres sources : c’est l’esprit critique qu’on veut développer." },
  { q: "Après avoir identifié les plans d’un paysage, quelle est l’étape suivante d’une lecture de paysage ?", choices: ["apprendre par cœur le nom du lieu", "recopier exactement la photographie", "repérer les éléments naturels et humains, puis réaliser un croquis légendé"], answer: 2, expl: "Démarche : 1) repérer les <b>plans</b> ; 2) distinguer les <b>éléments naturels</b> (relief, eau, végétation) et <b>humains</b> (habitat, routes, activités) ; 3) réaliser un <b>croquis</b> avec une légende organisée ; 4) se demander comment les hommes habitent ce lieu." },
  { q: "Quel site de l’IGN permet de consulter cartes et photographies aériennes du territoire français ?", answers: ["Géoportail", "Geoportail", "le Géoportail"], expl: "<b>Géoportail</b>, le site public de l’IGN, permet de superposer cartes, photos aériennes anciennes et récentes : très utile pour comparer l’évolution d’un quartier avec les élèves." },
  { q: "Dans un débat réglé, le rôle du secrétaire est de :", choices: ["noter les arguments échangés", "décider qui a gagné le débat", "distribuer la parole"], answer: 0, expl: "Le <b>secrétaire</b> garde la trace des <b>arguments</b> pour en faire la synthèse à la fin. C’est le <b>président de séance</b> qui distribue la parole, et un débat n’a pas de « gagnant »." },
  { q: "Dans un débat réglé, les élèves observateurs :", choices: ["donnent la bonne réponse à la fin", "observent le respect des règles et la circulation de la parole", "votent pour exclure ceux qui se trompent"], answer: 1, expl: "Les <b>observateurs</b> ne participent pas au débat : ils observent le <b>respect des règles</b>, la qualité de l’écoute et la répartition de la parole, puis en font un retour à la classe." },
  { type: 'vf', q: "Dans une discussion à visée philosophique, l’enseignant doit amener les élèves vers une réponse unique et correcte.", answer: 1, expl: "<b>Faux</b> : une DVP porte sur une question <b>ouverte</b>, sans réponse unique. L’enseignant aide à <b>argumenter</b>, à définir les mots et à écouter les autres, sans imposer sa réponse." },
  { q: "Quelle instance permet aux élèves de discuter et de réguler la vie de la classe ?", answers: ["conseil d’élèves", "conseil des élèves", "conseil de coopération", "conseil coopératif", "le conseil d’élèves", "le conseil de coopération"], expl: "Le <b>conseil d’élèves</b> (ou <b>conseil de coopération</b>) réunit régulièrement la classe pour parler des règles, des conflits et des projets : c’est un outil central de l’EMC." },
  { q: "Laquelle de ces questions relève d’une discussion à visée philosophique plutôt que d’un débat sur une règle de la classe ?", choices: ["Faut-il changer les règles de la cour de récréation ?", "Doit-on autoriser les jeux de ballon à la récréation ?", "Qu’est-ce qu’être juste ?"], answer: 2, expl: "« Qu’est-ce qu’être juste ? » interroge une <b>notion</b> abstraite : c’est une question philosophique. Les deux autres visent une <b>décision</b> pratique sur la vie collective, objet d’un débat réglé ou d’un conseil d’élèves." },
  { q: "Quelle progression respecte la démarche « du proche au lointain » en géographie ?", choices: ["le monde → la France → la commune → la classe", "la classe → l’école → le quartier → la commune", "la commune → la classe → le monde → l’école"], answer: 1, expl: "On part de l’espace <b>vécu</b> et observable (la classe, l’école), puis on élargit progressivement (quartier, commune, région…). Cela permet à l’élève de s’appuyer sur ce qu’il connaît." },
  { q: "Le plan de la classe représente l’espace vu :", choices: ["de face", "de côté, en perspective", "d’en haut (vue verticale)"], answer: 2, expl: "Un <b>plan</b> représente l’espace <b>vu d’en haut</b>, en vue verticale. Passer de la vue de face (dessin) à la vue de dessus est une difficulté réelle pour les jeunes élèves : la maquette et la photo aérienne aident." },
  { type: 'vf', q: "Sur une frise chronologique, il faut placer l’année 0 entre l’an −1 et l’an 1.", answer: 1, expl: "<b>Faux</b> : il n’existe <b>pas d’année 0</b> dans notre calendrier. On passe directement de l’an 1 av. J.-C. à l’an 1 apr. J.-C. Les élèves (et les adultes !) se trompent souvent." },
  { q: "Au cycle 2, construire une maquette du quartier aide surtout les élèves à :", choices: ["passer de l’espace vécu à sa représentation", "mémoriser les dates de l’histoire locale", "apprendre les noms des continents"], answer: 0, expl: "La <b>maquette</b> est une étape intermédiaire entre l’espace réel (en 3 dimensions) et le plan (en 2 dimensions, vu d’en haut) : elle aide à <b>représenter</b> l’espace vécu." },
  { q: "Comment appelle-t-on la représentation simplifiée d’un paysage ou d’un espace, réalisée à la main avec une légende ?", answers: ["croquis", "un croquis", "le croquis"], expl: "Le <b>croquis</b> simplifie la réalité pour en montrer l’essentiel : il a un titre, une légende organisée et des figurés. Ce n’est pas un dessin artistique, mais un outil de raisonnement." },
  { q: "Un élève affirme : « Les hommes préhistoriques chassaient les dinosaures. » Quel outil est le plus utile pour l’aider à corriger cette idée ?", choices: ["une frise chronologique à l’échelle sur un temps très long", "une carte du monde actuel", "un plan de l’école"], answer: 0, expl: "Les dinosaures non aviens ont disparu il y a environ <b>66 millions d’années</b>, les premiers humains apparaissent vers 3 millions d’années. Une <b>frise à l’échelle</b> rend visible cet écart immense, que les élèves sous-estiment." }
];
BANK['hgemc/hc4-medieval'] = [
  { q: "Quelle était la capitale de l’Empire byzantin ?", choices: ["Damas", "Constantinople", "Bagdad", "Rome"], answer: 1, expl: "L’Empire byzantin (Empire romain d’Orient) a pour capitale <b>Constantinople</b> (l’actuelle Istanbul), prise par les Ottomans en 1453. Rome est le siège du pape, Bagdad la capitale abbasside." },
  { q: "Quelle ville les croisés prennent-ils en 1099, au terme de la première croisade ?", answers: ["Jérusalem"], expl: "La première croisade (1095-1099) se termine par la prise de <b>Jérusalem</b> en juillet 1099, accompagnée de massacres. Les croisés y fondent des États latins d’Orient." },
  { q: "La Reconquista désigne :", choices: ["la reprise de Constantinople par les Byzantins", "la reconquête progressive de la péninsule Ibérique par les royaumes chrétiens", "la conquête de l’Amérique par les Espagnols"], answer: 1, expl: "La <b>Reconquista</b> (VIIIᵉ-XVᵉ siècle) est la reconquête de l’Espagne musulmane (Al-Andalus) par les royaumes chrétiens ; elle s’achève avec la prise de Grenade en <b>1492</b>." },
  { type: 'vf', q: "Les chiffres dits « arabes » ont été transmis à l’Occident par le monde musulman, mais ils viennent de l’Inde.", answer: 0, expl: "<b>Vrai</b> : ces chiffres et le zéro ont été inventés en <b>Inde</b>, puis adoptés et transmis par les savants du monde musulman (comme al-Khwârizmî). C’est un bel exemple d’<b>échanges</b> entre chrétientés et islam." },
  { q: "Comment s’appelle la cérémonie par laquelle le vassal jure fidélité à son seigneur ?", answers: ["hommage", "l’hommage", "l'hommage", "cérémonie de l’hommage"], expl: "Lors de l’<b>hommage</b>, le vassal place ses mains dans celles de son seigneur et lui jure fidélité ; il reçoit ensuite son fief (c’est l’investiture). Ne confonds pas hommage et fief." },
  { q: "Les banalités sont :", choices: ["des taxes payées pour utiliser le moulin, le four ou le pressoir du seigneur", "le service militaire dû par le vassal", "l’impôt versé à l’Église"], answer: 0, expl: "Les <b>banalités</b> sont des redevances que les paysans paient pour utiliser les équipements du seigneur (moulin, four, pressoir). L’impôt versé à l’Église, c’est la <b>dîme</b>." },
  { q: "Comment s’appelle l’impôt, environ un dixième des récoltes, versé à l’Église au Moyen Âge ?", answers: ["dîme", "la dîme", "dime", "la dime"], expl: "La <b>dîme</b> (du latin <i>decima</i>, « dixième ») est prélevée par l’Église sur les récoltes. Elle sera abolie en 1789, avec les privilèges." },
  { q: "Quelle abbaye bourguignonne, fondée en 910, est à l’origine d’un puissant ordre monastique ?", choices: ["Cluny", "Versailles", "Reims", "Chartres"], answer: 0, expl: "L’abbaye de <b>Cluny</b>, fondée en 910, devient le centre d’un vaste réseau de monastères. Cîteaux (1098), autre abbaye bourguignonne, donne naissance aux cisterciens. Chartres et Reims sont des cathédrales." },
  { q: "Quelle caractéristique appartient à l’art gothique ?", choices: ["des murs très épais percés de petites fenêtres", "des colonnes doriques et des frontons grecs", "de grands vitraux, des voûtes sur croisées d’ogives et des édifices très élevés"], answer: 2, expl: "L’art <b>gothique</b> (à partir du XIIᵉ siècle) utilise la croisée d’ogives et les arcs-boutants : on peut monter haut et ouvrir de grandes <b>verrières</b>. Les murs épais et les petites fenêtres caractérisent l’art <b>roman</b>." },
  { q: "La Hanse est :", choices: ["un ordre monastique fondé à Cîteaux", "un impôt royal sur le sel", "une association de villes marchandes de la mer du Nord et de la Baltique"], answer: 2, expl: "La <b>Hanse</b> regroupe des villes marchandes d’Europe du Nord (Lübeck, Hambourg, Bruges…), symbole de l’essor du commerce à partir du XIIᵉ siècle. L’impôt sur le sel s’appelle la gabelle." },
  { type: 'vf', q: "Saint Louis (Louis IX) est un roi de la dynastie capétienne.", answer: 0, expl: "<b>Vrai</b> : Louis IX (règne 1226-1270), petit-fils de Philippe Auguste, est un <b>Capétien</b>. Il mène deux croisades et meurt devant Tunis ; il est canonisé en 1297." },
  { q: "Quel navigateur portugais atteint l’Inde en contournant l’Afrique en 1498 ?", answers: ["Vasco de Gama", "Gama"], expl: "<b>Vasco de Gama</b> contourne le cap de Bonne-Espérance et atteint Calicut en Inde en <b>1498</b>, ouvrant la route maritime des épices pour le Portugal." },
  { q: "Hernán Cortés conquiert au début du XVIᵉ siècle l’empire :", choices: ["aztèque", "byzantin", "inca"], answer: 0, expl: "<b>Cortés</b> fait tomber l’empire <b>aztèque</b> (capitale Tenochtitlan, au Mexique) en 1521. C’est <b>Pizarro</b> qui conquiert l’empire inca, au Pérou." },
  { q: "Qui est le grand humaniste hollandais, auteur de l’<i>Éloge de la folie</i> (1511) ?", choices: ["Luther", "Érasme", "Colbert", "Calvin"], answer: 1, expl: "<b>Érasme</b> est le « prince des humanistes » : il étudie les textes anciens et la Bible dans leurs langues d’origine. Luther et Calvin sont des réformateurs, Colbert un ministre de Louis XIV." },
  { q: "Le concile de Trente (1545-1563) est associé à :", choices: ["le schisme de 1054", "la Réforme catholique", "la naissance du protestantisme"], answer: 1, expl: "Le <b>concile de Trente</b> réaffirme les dogmes catholiques et réforme l’Église (formation des prêtres) en réponse au protestantisme : c’est la <b>Réforme catholique</b> (ou Contre-Réforme)." },
  { q: "Quel réformateur français s’installe à Genève et y organise une Église protestante ?", answers: ["Calvin", "Jean Calvin"], expl: "<b>Jean Calvin</b>, né à Noyon, s’installe à Genève, qui devient la « Rome protestante ». Le calvinisme se diffuse en France : ses fidèles sont appelés les huguenots." },
  { type: 'vf', q: "Louis XIV gouverne seul, sans Premier ministre, à partir de 1661.", answer: 0, expl: "<b>Vrai</b> : à la mort de Mazarin en <b>1661</b>, Louis XIV décide de gouverner personnellement, sans principal ministre : c’est le début de son règne personnel, qui dure jusqu’en 1715." },
  { q: "Sous Louis XIV, les intendants sont :", choices: ["des prêtres chargés de collecter la dîme", "des représentants du roi chargés d’appliquer ses décisions dans les provinces", "des seigneurs élus par les paysans"], answer: 1, expl: "Les <b>intendants</b>, nommés et révocables par le roi, contrôlent la justice, la police et les finances dans les provinces : ce sont des instruments de la <b>centralisation</b> monarchique." },
  { q: "Combien d’années séparent l’édit de Nantes (1598) de sa révocation (1685) ?", answers: ["87", "87 ans"], expl: "1685 − 1598 = <b>87 ans</b>. Pendant près d’un siècle, les protestants ont bénéficié d’une liberté de culte limitée, supprimée par Louis XIV avec l’édit de Fontainebleau." },
  { type: 'vf', q: "Selon la monarchie de droit divin, Louis XIV tient son pouvoir du peuple.", answer: 1, expl: "<b>Faux</b> : dans une monarchie de <b>droit divin</b>, le roi affirme tenir son pouvoir de <b>Dieu</b> (il est sacré à Reims) et n’a de comptes à rendre qu’à lui. L’idée de souveraineté du peuple viendra des Lumières." }
];
BANK['hgemc/hc4-revolutions'] = [
  { q: "Quelle idée Voltaire défend-il en priorité ?", choices: ["la tolérance religieuse", "la souveraineté du peuple", "la séparation des pouvoirs"], answer: 0, expl: "<b>Voltaire</b> combat le fanatisme et défend la <b>tolérance</b> (affaire Calas, <i>Traité sur la tolérance</i>, 1763). La séparation des pouvoirs est l’idée de Montesquieu, la souveraineté du peuple celle de Rousseau." },
  { q: "Où les idées des Lumières se diffusent-elles au XVIIIᵉ siècle ?", choices: ["dans les salons, les cafés et les académies", "uniquement dans les monastères", "dans les usines et les mines"], answer: 0, expl: "Les idées des Lumières circulent dans les <b>salons</b> (souvent tenus par des femmes), les <b>cafés</b>, les <b>académies</b> et par les livres et journaux, malgré la censure." },
  { q: "Quel serment les députés du tiers état prêtent-ils le 20 juin 1789 ?", answers: ["Jeu de paume", "serment du Jeu de paume", "le serment du Jeu de paume"], expl: "Le 20 juin 1789, dans la salle du <b>Jeu de paume</b> à Versailles, les députés jurent de ne pas se séparer avant d’avoir donné une Constitution à la France : ils affirment la souveraineté de la nation." },
  { q: "La monarchie constitutionnelle est instaurée par la Constitution de :", choices: ["1793", "1804", "1815", "1791"], answer: 3, expl: "La Constitution de <b>1791</b> fait de la France une <b>monarchie constitutionnelle</b> : le roi partage le pouvoir avec une Assemblée élue. Elle dure moins d’un an : la monarchie tombe le 10 août 1792." },
  { q: "En quelle année la Constitution des États-Unis est-elle rédigée ?", answers: ["1787"], expl: "La Constitution des États-Unis est rédigée en <b>1787</b> à Philadelphie, onze ans après la Déclaration d’indépendance (1776). Elle organise une république fédérale et la séparation des pouvoirs." },
  { q: "La Terreur correspond à la période :", choices: ["1815-1830", "1793-1794", "1789-1790"], answer: 1, expl: "La <b>Terreur</b> (1793-1794) est une période de répression contre les « ennemis de la Révolution », dominée par Robespierre ; elle s’achève avec sa chute en juillet 1794 (9 Thermidor)." },
  { q: "En quelle année Bonaparte prend-il le pouvoir par un coup d’État ?", answers: ["1799"], expl: "Le coup d’État du 18 Brumaire an VIII (9 novembre <b>1799</b>) met fin au Directoire : Bonaparte devient Premier consul. Il sera sacré empereur en 1804." },
  { type: 'vf', q: "Napoléon Bonaparte conserve l’égalité civile issue de la Révolution, mais il rétablit l’esclavage.", answer: 0, expl: "<b>Vrai</b> : le Code civil (1804) consacre l’<b>égalité devant la loi</b>, mais Bonaparte <b>rétablit l’esclavage</b> en 1802 et instaure un régime autoritaire. Son bilan est donc ambivalent." },
  { q: "La monarchie de Juillet commence en :", choices: ["1852", "1830", "1848", "1815"], answer: 1, expl: "Après la révolution des « Trois Glorieuses » (juillet <b>1830</b>), Louis-Philippe devient « roi des Français » : c’est la monarchie de Juillet, renversée par la révolution de 1848." },
  { q: "Quel empereur dirige le Second Empire (1852-1870) ?", answers: ["Napoléon III", "Napoléon 3", "Louis-Napoléon Bonaparte", "Louis Napoléon Bonaparte"], expl: "<b>Napoléon III</b>, neveu de Napoléon Iᵉʳ, élu président en 1848 sous le nom de Louis-Napoléon Bonaparte, prend le pouvoir par un coup d’État (1851) et devient empereur en 1852. Il tombe après la défaite de Sedan (1870)." },
  { q: "Quel est l’ordre chronologique des régimes en France entre 1815 et 1870 ?", choices: ["Restauration → monarchie de Juillet → IIᵉ République → Second Empire", "monarchie de Juillet → Restauration → Second Empire → IIᵉ République", "IIᵉ République → Restauration → Second Empire → monarchie de Juillet"], answer: 0, expl: "<b>Restauration</b> (1815-1830, Louis XVIII puis Charles X) → <b>monarchie de Juillet</b> (1830-1848) → <b>IIᵉ République</b> (1848-1852) → <b>Second Empire</b> (1852-1870). Puis vient la IIIᵉ République." },
  { q: "Quelles innovations caractérisent la deuxième industrialisation (fin du XIXᵉ siècle) ?", choices: ["le charbon, la machine à vapeur, le textile", "l’électricité, le pétrole, la chimie, l’automobile", "le nucléaire et l’informatique"], answer: 1, expl: "La <b>deuxième industrialisation</b> repose sur l’<b>électricité</b>, le <b>pétrole</b>, la <b>chimie</b> et l’automobile. Le charbon et la vapeur caractérisent la première ; le nucléaire et l’informatique viennent après 1945." },
  { type: 'vf', q: "La machine à vapeur, perfectionnée par James Watt, est au cœur de la première industrialisation.", answer: 0, expl: "<b>Vrai</b> : vers 1769, l’Écossais <b>James Watt</b> améliore la machine à vapeur, qui va actionner les machines textiles, les pompes des mines puis les locomotives." },
  { q: "Quelle conséquence sociale l’industrialisation entraîne-t-elle au XIXᵉ siècle ?", choices: ["la naissance d’un monde ouvrier nombreux dans les villes", "le retour massif des citadins à la campagne", "la disparition de la bourgeoisie"], answer: 0, expl: "L’industrialisation fait naître un <b>monde ouvrier</b> concentré dans les villes industrielles, aux conditions de vie difficiles. La <b>bourgeoisie</b>, elle, s’enrichit et s’affirme." },
  { q: "En quelle année la IIIᵉ République est-elle proclamée (le 4 septembre) ?", answers: ["1870"], expl: "La IIIᵉ République est proclamée le 4 septembre <b>1870</b>, après la défaite de Napoléon III à Sedan face à la Prusse. Elle durera jusqu’en 1940, le plus long régime depuis 1789." },
  { q: "La grande loi sur la liberté de la presse date de :", choices: ["1884", "1905", "1881", "1848"], answer: 2, expl: "La loi du 29 juillet <b>1881</b> sur la liberté de la presse est toujours en vigueur. 1884, c’est la loi sur les syndicats ; 1905, la séparation des Églises et de l’État." },
  { q: "Quel écrivain publie « J’accuse… ! » en 1898 pour défendre le capitaine Dreyfus ?", answers: ["Zola", "Émile Zola", "Emile Zola"], expl: "<b>Émile Zola</b> publie « J’accuse… ! » dans le journal <i>L’Aurore</i> le 13 janvier 1898 : il dénonce l’injustice faite à Dreyfus. Condamné pour diffamation, il doit s’exiler en Angleterre." },
  { type: 'vf', q: "Sous la IIIᵉ République, les femmes obtiennent le droit de vote.", answer: 1, expl: "<b>Faux</b> : malgré les combats des suffragistes, les femmes restent exclues du vote sous la IIIᵉ République (1870-1940). Elles l’obtiennent en <b>1944</b> par une ordonnance du gouvernement provisoire." },
  { q: "Un élève écrit : « Le 14 juillet 1789, les révolutionnaires proclament la République. » Quelle correction lui proposes-tu ?", choices: ["La République a été proclamée par Napoléon en 1804", "Il a raison, la République est proclamée le jour de la prise de la Bastille", "Le 14 juillet 1789 est la prise de la Bastille ; la République n’est proclamée qu’en septembre 1792"], answer: 2, expl: "En 1789, la France reste une <b>monarchie</b> : le roi est encore là, et on cherche à limiter son pouvoir (monarchie constitutionnelle en 1791). La <b>République</b> n’est proclamée qu’en <b>septembre 1792</b>, après la chute de la monarchie." },
  { type: 'vf', q: "La France a commencé la conquête de l’Algérie avant la proclamation de la IIIᵉ République.", answer: 0, expl: "<b>Vrai</b> : la conquête de l’Algérie commence en <b>1830</b> (prise d’Alger), sous Charles X, donc bien avant 1870. La IIIᵉ République accélère ensuite l’expansion coloniale en Afrique et en Asie." }
];
BANK['hgemc/hc4-guerres'] = [
  { q: "En 1914, la Triple Entente regroupe :", choices: ["la France, l’Allemagne et la Russie", "l’Allemagne, l’Autriche-Hongrie et l’Italie", "la France, le Royaume-Uni et la Russie"], answer: 2, expl: "La <b>Triple Entente</b> unit la <b>France</b>, le <b>Royaume-Uni</b> et la <b>Russie</b>. En face, les puissances centrales : Allemagne et Autriche-Hongrie (l’Italie, d’abord membre de la Triple Alliance, rejoint l’Entente en 1915)." },
  { q: "En quelle année a lieu la bataille de Verdun ?", answers: ["1916"], expl: "La bataille de <b>Verdun</b> dure de février à décembre <b>1916</b>, comme celle de la Somme (juillet-novembre 1916). C’est l’année des grandes batailles d’usure." },
  { q: "Lequel de ces faits illustre la notion de guerre totale en 1914-1918 ?", choices: ["seuls les soldats de métier combattent", "les femmes remplacent les hommes dans les usines d’armement", "les civils restent totalement à l’écart du conflit"], answer: 1, expl: "Dans une <b>guerre totale</b>, toute la société est mobilisée : l’économie tourne vers l’armement et les <b>femmes</b> (les « munitionnettes ») travaillent à l’usine. Les civils sont aussi touchés par la propagande, les privations, l’occupation." },
  { q: "Quel pays entre en guerre en 1917 aux côtés de l’Entente ?", answers: ["États-Unis", "les États-Unis", "Etats-Unis", "USA"], expl: "Les <b>États-Unis</b> entrent en guerre en avril <b>1917</b>, notamment à cause de la guerre sous-marine allemande. Leur arrivée compense le retrait de la Russie après la révolution bolchevique." },
  { type: 'vf', q: "La bataille de la Somme a eu lieu en 1916.", answer: 0, expl: "<b>Vrai</b> : l’offensive franco-britannique de la <b>Somme</b> (juillet-novembre 1916) fait plus d’un million de victimes (tués, blessés, disparus) pour quelques kilomètres gagnés." },
  { q: "Le goulag désigne :", choices: ["la police politique nazie", "le système des camps de travail forcé en URSS", "le parti unique italien"], answer: 1, expl: "Le <b>goulag</b> est l’administration des camps de travail forcé soviétiques, où des millions de détenus ont été envoyés sous Staline. La police politique nazie, c’est la <b>Gestapo</b>." },
  { q: "La Grande Terreur stalinienne s’étend de 1936 à quelle année ?", answers: ["1938"], expl: "La <b>Grande Terreur</b> (1936-<b>1938</b>) frappe des cadres du parti, des militaires et de simples citoyens : environ 700 000 personnes sont exécutées et des centaines de milliers envoyées au goulag." },
  { q: "La SS et la Gestapo sont des instruments de terreur :", choices: ["de la IIIᵉ République", "de l’URSS de Staline", "de l’Allemagne nazie"], answer: 2, expl: "La <b>SS</b> (milice du parti nazi) et la <b>Gestapo</b> (police politique) sont les instruments de la terreur nazie. En URSS, la police politique s’appelle le NKVD." },
  { type: 'vf', q: "Les régimes totalitaires cherchent à encadrer toute la société, y compris la jeunesse.", answer: 0, expl: "<b>Vrai</b> : l’embrigadement commence dès l’enfance (Jeunesses hitlériennes, Komsomol en URSS). Le but est de façonner un « <b>homme nouveau</b> » conforme à l’idéologie." },
  { q: "En quelle année l’Allemagne envahit-elle la Pologne, déclenchant la Seconde Guerre mondiale en Europe ?", answers: ["1939", "1er septembre 1939", "1ᵉʳ septembre 1939"], expl: "Le 1ᵉʳ septembre <b>1939</b>, l’Allemagne envahit la Pologne ; le Royaume-Uni et la France lui déclarent la guerre le 3 septembre." },
  { q: "Quel événement de décembre 1941 fait entrer les États-Unis dans la guerre ?", choices: ["l’attaque japonaise de Pearl Harbor", "la bataille de Stalingrad", "le débarquement en Normandie"], answer: 0, expl: "Le 7 décembre 1941, le Japon attaque la base américaine de <b>Pearl Harbor</b> (Hawaï) : les États-Unis entrent en guerre et le conflit devient vraiment mondial. Stalingrad commence en 1942, le débarquement a lieu en 1944." },
  { q: "L’armistice entre la France et l’Allemagne est signé le :", choices: ["22 juin 1940", "11 novembre 1918", "8 mai 1945", "18 juin 1940"], answer: 0, expl: "L’armistice est signé le <b>22 juin 1940</b> à Rethondes : la France est en partie occupée. Le 18 juin 1940, c’est l’appel de De Gaulle, qui refuse justement cette défaite." },
  { q: "Quel est le plus grand centre de mise à mort nazi, situé en Pologne ?", answers: ["Auschwitz-Birkenau", "Auschwitz", "Birkenau", "Auschwitz Birkenau"], expl: "À <b>Auschwitz-Birkenau</b>, environ 1,1 million de personnes, dont près d’un million de Juifs, ont été assassinées, la plupart dans les chambres à gaz dès leur arrivée." },
  { q: "Sur quelles villes les États-Unis lancent-ils des bombes atomiques en août 1945 ?", choices: ["Berlin et Dresde", "Hiroshima et Nagasaki", "Tokyo et Kyoto"], answer: 1, expl: "Les bombes atomiques frappent <b>Hiroshima</b> (6 août) et <b>Nagasaki</b> (9 août 1945) ; le Japon capitule le 2 septembre 1945. Dresde a été détruite par des bombardements classiques." },
  { type: 'vf', q: "La rafle du Vél’ d’Hiv a été menée par la seule police allemande.", answer: 1, expl: "<b>Faux</b> : la rafle des 16 et 17 juillet 1942 a été menée par la <b>police française</b>, à la demande des nazis et avec l’accord du gouvernement de Vichy. La responsabilité de l’État français a été reconnue en 1995." },
  { q: "Que signifie le sigle CNR, créé par Jean Moulin en 1943 ?", answers: ["Conseil national de la Résistance", "le Conseil national de la Résistance"], expl: "Le <b>Conseil national de la Résistance</b> réunit les mouvements, les partis et les syndicats résistants. Son programme (1944) inspire les grandes réformes de la Libération, comme la Sécurité sociale." },
  { q: "Quel est le nom officiel du régime de Vichy ?", choices: ["la République française", "l’Empire français", "l’État français"], answer: 2, expl: "Pétain supprime la République et instaure l’« <b>État français</b> », un régime autoritaire. Le mot « République » disparaît, tout comme la devise républicaine, remplacée par « Travail, Famille, Patrie »." },
  { type: 'vf', q: "Hitler arrive au pouvoir en 1933 par un coup d’État militaire.", answer: 1, expl: "<b>Faux</b> : Hitler est <b>nommé</b> chancelier de façon légale par le président Hindenburg en janvier 1933, après les succès électoraux du parti nazi. C’est ensuite qu’il détruit la démocratie de l’intérieur." },
  { q: "Une affiche soviétique des années 1930 montre Staline souriant, entouré d’enfants heureux. Quel est son objectif ?", choices: ["dénoncer la Grande Terreur", "construire le culte du chef par la propagande", "montrer objectivement la vie quotidienne en URSS"], answer: 1, expl: "C’est une affiche de <b>propagande</b> : elle présente Staline comme un père bienveillant pour construire le <b>culte du chef</b>, au moment même où la terreur frappe le pays. Il faut toujours confronter l’image à la réalité historique." },
  { q: "Pourquoi parle-t-on de « guerre d’anéantissement » pour la Seconde Guerre mondiale ?", choices: ["parce que seules les armées professionnelles s’affrontent", "parce que les belligérants cherchent à détruire totalement l’ennemi, y compris les populations civiles", "parce que la guerre a été très courte"], answer: 1, expl: "La guerre vise à <b>anéantir</b> l’adversaire : bombardements de villes, massacres de civils, génocide des Juifs et des Tsiganes, surtout sur le front de l’Est. Les civils représentent plus de la moitié des morts." }
];
BANK['hgemc/hc4-depuis1945'] = [
  { q: "Le blocus de Berlin, première grande crise de la guerre froide, a lieu en :", choices: ["1989", "1948-1949", "1961"], answer: 1, expl: "En <b>1948-1949</b>, Staline bloque les accès terrestres à Berlin-Ouest ; les Américains organisent un pont aérien pour ravitailler la ville. 1961, c’est la construction du mur ; 1989, sa chute." },
  { q: "La guerre de Corée commence en 1950 : en quelle année se termine-t-elle ?", answers: ["1953"], expl: "La guerre de Corée (1950-<b>1953</b>) oppose le Nord communiste, soutenu par la Chine et l’URSS, au Sud soutenu par les États-Unis et l’ONU. Elle se termine par un armistice, sans traité de paix." },
  { q: "Quel modèle politique et économique caractérise le bloc de l’Est ?", choices: ["la démocratie libérale et l’économie de marché", "la monarchie constitutionnelle", "le communisme, avec un parti unique et une économie planifiée"], answer: 2, expl: "Le bloc de l’Est, dominé par l’URSS, repose sur le <b>communisme</b> : parti unique, économie <b>planifiée</b> par l’État. Le bloc de l’Ouest défend la démocratie libérale et le capitalisme." },
  { q: "En quelle année l’Allemagne est-elle réunifiée ?", answers: ["1990"], expl: "L’Allemagne est réunifiée le 3 octobre <b>1990</b>, moins d’un an après la chute du mur de Berlin (9 novembre 1989). Attention à ne pas confondre les deux dates." },
  { type: 'vf', q: "Pendant la guerre froide, les États-Unis et l’URSS se sont affrontés directement par les armes.", answer: 1, expl: "<b>Faux</b> : les deux Grands ne se sont <b>jamais</b> affrontés directement, à cause de la dissuasion nucléaire. Ils se sont opposés par alliés interposés (Corée, Vietnam), par la propagande et la course aux armements." },
  { q: "En quelle année l’Inde devient-elle indépendante ?", answers: ["1947"], expl: "L’Inde devient indépendante du Royaume-Uni en <b>1947</b>, après la lutte non violente menée par Gandhi. Elle est séparée du Pakistan, dans de terribles violences." },
  { q: "La conférence de Bandung (1955) marque :", choices: ["la fin de la guerre froide", "l’affirmation des pays du tiers-monde", "la création de la CECA"], answer: 1, expl: "À <b>Bandung</b> (Indonésie), 29 pays d’Asie et d’Afrique condamnent le colonialisme et affirment leur refus d’être alignés : c’est l’émergence du <b>tiers-monde</b>." },
  { q: "La CECA (Communauté européenne du charbon et de l’acier) est créée en :", choices: ["1992", "1945", "1957", "1951"], answer: 3, expl: "La <b>CECA</b> est créée en <b>1951</b> (traité de Paris), sur une idée de Robert Schuman et Jean Monnet : mettre en commun le charbon et l’acier rend la guerre entre Français et Allemands impossible. La CEE suit en 1957." },
  { q: "En quelle année le Parlement européen est-il élu pour la première fois au suffrage universel direct ?", answers: ["1979"], expl: "En <b>1979</b>, les citoyens européens élisent pour la première fois directement leurs députés européens. Simone Veil devient alors la première présidente du Parlement européen élu." },
  { type: 'vf', q: "Le Royaume-Uni a quitté l’Union européenne en 2020.", answer: 0, expl: "<b>Vrai</b> : après le référendum de 2016, le <b>Brexit</b> devient effectif le 31 janvier <b>2020</b>. L’UE passe alors de 28 à 27 membres." },
  { q: "La IVᵉ République est instaurée en :", choices: ["1958", "1946", "1962", "1944"], answer: 1, expl: "La Constitution de la IVᵉ République est adoptée en <b>1946</b>. Instable (gouvernements renversés très souvent), elle s’effondre en 1958 dans la crise algérienne, laissant place à la Vᵉ République." },
  { q: "La loi Neuwirth (1967) autorise :", choices: ["le divorce par consentement mutuel", "l’interruption volontaire de grossesse", "la contraception"], answer: 2, expl: "La loi <b>Neuwirth</b> (1967) autorise la <b>contraception</b> (la pilule). L’IVG est autorisée en 1975 par la loi Veil. Les deux sont des étapes de l’émancipation des femmes." },
  { type: 'vf', q: "Les femmes votent pour la première fois en France en 1945.", answer: 0, expl: "<b>Vrai</b> : le droit de vote leur est accordé par l’ordonnance de <b>1944</b>, et elles votent pour la première fois aux élections municipales d’avril <b>1945</b>. Le piège : confondre la date du droit et celle du premier vote." },
  { q: "Les « Trente Glorieuses » désignent :", choices: ["les trente premières années de l’Union européenne", "la forte croissance économique des pays industrialisés de 1945 à 1975 environ", "une guerre de trente ans en Europe"], answer: 1, expl: "L’expression (de l’économiste Jean Fourastié) désigne les trente années de forte <b>croissance</b>, de plein emploi et d’essor de la <b>société de consommation</b>, de 1945 au premier choc pétrolier (1973-1975)." },
  { q: "Qui est le premier président de la Vᵉ République ?", answers: ["de Gaulle", "Charles de Gaulle", "général de Gaulle", "le général de Gaulle", "Gaulle"], expl: "Le général <b>Charles de Gaulle</b> est élu président en décembre 1958 (par un collège de grands électeurs), puis réélu en 1965 au suffrage universel direct. Il démissionne en 1969." },
  { q: "On parle de cohabitation lorsque :", choices: ["le Président et le Premier ministre appartiennent à des majorités politiques opposées", "deux présidents gouvernent ensemble", "l’Assemblée et le Sénat fusionnent"], answer: 0, expl: "Il y a <b>cohabitation</b> quand la majorité de l’Assemblée nationale est opposée au Président, qui doit nommer un Premier ministre du camp adverse. Exemple : Mitterrand et Chirac (1986-1988)." },
  { q: "Mai 1968 est :", choices: ["un mouvement de contestation étudiante suivi d’une grève générale", "la date de la fin de la guerre d’Algérie", "le début de la construction européenne"], answer: 0, expl: "En <b>mai 1968</b>, une révolte étudiante contre l’autorité et la société de consommation se transforme en <b>grève générale</b> (plusieurs millions de grévistes). Elle aboutit aux accords de Grenelle." },
  { type: 'vf', q: "Les pièces et billets en euros circulent dès la signature du traité de Maastricht en 1992.", answer: 1, expl: "<b>Faux</b> : Maastricht (1992) <b>prévoit</b> la monnaie unique, mais les pièces et billets ne circulent que le 1ᵉʳ janvier <b>2002</b>, dix ans plus tard." },
  { q: "Qui construit le mur de Berlin en 1961 ?", choices: ["la RFA (Allemagne de l’Ouest)", "les États-Unis", "la RDA (Allemagne de l’Est)"], answer: 2, expl: "C’est la <b>RDA</b>, soutenue par l’URSS, qui construit le mur pour empêcher ses habitants de fuir vers Berlin-Ouest. Il devient le symbole de la division de l’Europe." },
  { q: "La loi d’abolition de la peine de mort (1981) est défendue par :", choices: ["Simone Veil", "Jules Ferry", "Charles de Gaulle", "Robert Badinter"], answer: 3, expl: "Le garde des Sceaux <b>Robert Badinter</b> défend l’abolition devant l’Assemblée nationale en septembre <b>1981</b>. Simone Veil est associée à la loi sur l’IVG (1975)." }
];
BANK['hgemc/gc4-monde'] = [
  { q: "Un pays enregistre en un an 800 000 naissances, 600 000 décès et un solde migratoire de +150 000. De combien sa population augmente-t-elle ?", answers: ["350000", "350 000", "+350000", "+350 000"], expl: "Solde naturel = 800 000 − 600 000 = 200 000. Croissance = solde naturel + solde migratoire = 200 000 + 150 000 = <b>350 000</b> habitants." },
  { q: "Un pays compte 1 200 000 naissances et 1 500 000 décès en un an. Quel est son solde naturel ?", answers: ["-300000", "−300000", "-300 000", "−300 000"], expl: "Solde naturel = naissances − décès = 1 200 000 − 1 500 000 = <b>−300 000</b>. Il est <b>négatif</b> : sans immigration, la population diminue (c’est le cas du Japon ou de l’Italie)." },
  { type: 'vf', q: "Au cours de la transition démographique, la natalité baisse avant la mortalité.", answer: 1, expl: "<b>Faux</b> : c’est la <b>mortalité</b> qui baisse d’abord (progrès de l’hygiène, de la médecine, de l’alimentation), puis la natalité. Entre les deux, la population augmente très vite." },
  { q: "La valeur de l’IDH est comprise entre :", choices: ["1 et 10", "0 et 100", "0 et 1"], answer: 2, expl: "L’IDH varie de <b>0 à 1</b> : plus il est proche de 1, plus le développement est élevé (la Suisse ou la Norvège dépassent 0,96 ; certains pays d’Afrique subsaharienne sont sous 0,4)." },
  { q: "Le stress hydrique désigne :", choices: ["une pollution des eaux par les industries", "une inondation catastrophique", "une situation où la demande en eau dépasse les ressources disponibles"], answer: 2, expl: "On parle de <b>stress hydrique</b> quand les ressources en eau disponibles ne suffisent pas à couvrir les besoins (agriculture, villes, industrie). Il touche notamment le Maghreb, le Moyen-Orient, l’Inde." },
  { q: "Laquelle de ces sources d’énergie n’est PAS une énergie fossile ?", choices: ["le gaz naturel", "le charbon", "l’uranium (nucléaire)", "le pétrole"], answer: 2, expl: "Charbon, pétrole et gaz sont des énergies <b>fossiles</b> (issues de la décomposition d’êtres vivants). L’<b>uranium</b> est un minerai : il n’est pas fossile, mais il n’est pas renouvelable non plus. Piège classique !" },
  { type: 'vf', q: "Un séisme dans un désert totalement inhabité constitue un risque majeur.", answer: 1, expl: "<b>Faux</b> : il y a un <b>aléa</b>, mais pas de <b>vulnérabilité</b> (ni population ni biens exposés). Or risque = aléa × vulnérabilité : sans enjeu humain, il n’y a pas de risque." },
  { q: "Quelle est la cause principale du changement climatique actuel ?", choices: ["les variations naturelles de l’orbite terrestre", "le trou dans la couche d’ozone", "les émissions de gaz à effet de serre liées aux activités humaines"], answer: 2, expl: "Le réchauffement actuel est dû surtout aux <b>gaz à effet de serre</b> (CO₂, méthane) émis par les activités humaines (énergies fossiles, déforestation). Le trou dans la couche d’ozone est un autre problème, qui n’en est pas la cause." },
  { q: "Comment appelle-t-on l’extension des villes sur les espaces ruraux qui les entourent ?", answers: ["étalement urbain", "l’étalement urbain", "l'étalement urbain"], expl: "L’<b>étalement urbain</b> consomme des terres agricoles et allonge les déplacements. Les villes durables cherchent à le limiter en densifiant les quartiers existants." },
  { q: "Les quartiers d’habitat précaire construits sans autorisation, dans de nombreuses villes des pays du Sud, sont appelés :", choices: ["bidonvilles ou quartiers informels", "quartiers d’affaires", "villes nouvelles"], answer: 0, expl: "Les <b>bidonvilles</b> (favelas au Brésil, slums en Inde) sont des <b>quartiers informels</b> sans titre de propriété, souvent sans eau courante ni assainissement. Environ 1 milliard de personnes y vivent." },
  { q: "Quel détroit, entre l’Iran et la péninsule Arabique, est un passage majeur du pétrole mondial ?", choices: ["Gibraltar", "Ormuz", "Malacca", "le Bosphore"], answer: 1, expl: "Le détroit d’<b>Ormuz</b> relie le golfe Persique à l’océan Indien : environ un cinquième du pétrole consommé dans le monde y transite. Gibraltar sépare l’Europe de l’Afrique." },
  { q: "Quel canal relie l’océan Atlantique à l’océan Pacifique ?", answers: ["Panama", "canal de Panama", "le canal de Panama"], expl: "Le canal de <b>Panama</b> (ouvert en 1914) évite aux navires le contournement de l’Amérique du Sud. Ne le confonds pas avec <b>Suez</b>, entre Méditerranée et mer Rouge." },
  { q: "La Northern Range désigne :", choices: ["une chaîne de montagnes du Canada", "le cercle polaire arctique", "la façade maritime d’Europe du Nord-Ouest, du Havre à Hambourg"], answer: 2, expl: "La <b>Northern Range</b> est la façade maritime la plus active d’Europe, avec les grands ports du Havre, d’Anvers, de <b>Rotterdam</b> et de Hambourg." },
  { q: "Quel est le premier port mondial pour le trafic de conteneurs ?", choices: ["Marseille", "New York", "Rotterdam", "Shanghai"], answer: 3, expl: "<b>Shanghai</b> (Chine) est le premier port à conteneurs du monde, devant Singapour. Les plus grands ports mondiaux sont en Asie orientale ; Rotterdam est le premier port d’<b>Europe</b>." },
  { q: "Comment s’appelle la grande boîte métallique standardisée qui sert à transporter les marchandises par bateau, train ou camion ?", answers: ["conteneur", "le conteneur", "un conteneur", "container"], expl: "Le <b>conteneur</b> (inventé dans les années 1950) se transfère facilement d’un mode de transport à l’autre : il a fait chuter le coût du transport et accéléré la mondialisation." },
  { type: 'vf', q: "Les données Internet circulent entre les continents essentiellement grâce à des câbles sous-marins.", answer: 0, expl: "<b>Vrai</b> : plus de 95 % des données intercontinentales passent par des <b>câbles sous-marins</b> en fibre optique, et non par les satellites. Ce sont des infrastructures stratégiques de la mondialisation." },
  { q: "Laquelle de ces villes est une grande place financière mondiale ?", choices: ["Londres", "Lagos", "Rotterdam"], answer: 0, expl: "<b>Londres</b>, comme New York ou Tokyo, concentre banques, bourses et sièges de grandes entreprises : c’est une <b>place financière</b> mondiale. Rotterdam est un grand port, Lagos une mégapole africaine." },
  { q: "Un réfugié est une personne qui :", choices: ["part travailler quelques mois à l’étranger", "voyage à l’étranger pour ses vacances", "a fui son pays à cause de persécutions ou d’une guerre et y bénéficie d’une protection internationale"], answer: 2, expl: "Le statut de <b>réfugié</b> (convention de Genève, 1951) protège les personnes qui fuient des persécutions. Ne le confonds pas avec le touriste ni avec le migrant économique." },
  { type: 'vf', q: "Le détroit de Gibraltar relie la mer Méditerranée à l’océan Atlantique.", answer: 0, expl: "<b>Vrai</b> : large d’environ 14 km, le détroit de <b>Gibraltar</b> sépare l’Espagne du Maroc et relie la Méditerranée à l’Atlantique. C’est un passage maritime très fréquenté." },
  { q: "Laquelle de ces mesures caractérise une ville durable ?", choices: ["développer les transports en commun et limiter l’étalement urbain", "construire de nouvelles autoroutes urbaines", "étendre les zones commerciales en périphérie"], answer: 0, expl: "Une <b>ville durable</b> réduit son impact environnemental tout en restant vivable : transports en commun, pistes cyclables, écoquartiers, densification. Les autoroutes et les zones commerciales en périphérie favorisent au contraire la voiture et l’étalement." }
];
BANK['hgemc/gc4-france'] = [
  { q: "Selon l’Insee, quelle part des Français vit dans l’aire d’attraction d’une ville ?", choices: ["environ 1 sur 2", "environ 3 sur 10", "plus de 9 sur 10"], answer: 2, expl: "Plus de <b>9 Français sur 10</b> vivent dans l’aire d’attraction d’une ville (ville-centre, banlieue, couronne). Même beaucoup de « ruraux » dépendent de la ville pour leur travail." },
  { q: "De la ville vers ses marges, quel est l’ordre des espaces d’une aire urbaine ?", choices: ["banlieue → couronne périurbaine → ville-centre", "couronne périurbaine → ville-centre → banlieue", "ville-centre → banlieue → couronne périurbaine"], answer: 2, expl: "Au cœur, la <b>ville-centre</b> ; autour, la <b>banlieue</b>, urbanisée en continu ; plus loin, la <b>couronne périurbaine</b>, mêlant lotissements et champs, dont les habitants travaillent souvent dans le pôle urbain." },
  { type: 'vf', q: "La périurbanisation rend les habitants très dépendants de la voiture.", answer: 0, expl: "<b>Vrai</b> : dans les couronnes périurbaines, les transports en commun sont rares et les distances longues : la <b>voiture</b> est indispensable pour les trajets pendulaires, avec des coûts et une pollution importants." },
  { q: "Quelle grande région agricole française est spécialisée dans la culture des céréales (blé) ?", answers: ["Bassin parisien", "le Bassin parisien", "Beauce", "la Beauce"], expl: "Le <b>Bassin parisien</b> (avec la Beauce, la Brie, la Picardie) est la grande région céréalière : vastes exploitations, très mécanisées, aux rendements parmi les plus élevés du monde." },
  { q: "Quelle région française est spécialisée dans l’élevage intensif (porcs, volailles, lait) ?", choices: ["la Corse", "l’Île-de-France", "la Bretagne"], answer: 2, expl: "La <b>Bretagne</b> (et l’Ouest en général) est la première région d’élevage intensif, liée à une forte industrie agroalimentaire. Cela pose des problèmes de pollution (algues vertes)." },
  { q: "Quel technopôle, près de Nice, est l’un des premiers d’Europe ?", answers: ["Sophia Antipolis", "Sophia-Antipolis"], expl: "<b>Sophia Antipolis</b>, créé en 1969, regroupe entreprises de haute technologie, centres de recherche et formations supérieures, dans un cadre attractif proche de la Méditerranée." },
  { q: "La désindustrialisation désigne :", choices: ["l’installation d’usines à la campagne", "la création de nouvelles usines", "la baisse de la part de l’industrie dans les emplois et l’économie"], answer: 2, expl: "La <b>désindustrialisation</b> touche la France depuis les années 1970 (mines, sidérurgie, textile) : fermetures d’usines, délocalisations, reconversion difficile de régions comme le Nord ou la Lorraine." },
  { type: 'vf', q: "La France est l’une des premières destinations touristiques mondiales.", answer: 0, expl: "<b>Vrai</b> : avec environ 100 millions de visiteurs internationaux par an, la France est la <b>première</b> destination touristique mondiale en nombre d’arrivées (patrimoine, littoraux, montagnes, gastronomie)." },
  { q: "On appelle « néoruraux » :", choices: ["des citadins qui s’installent à la campagne", "des touristes qui visitent les fermes", "des agriculteurs qui partent en ville"], answer: 0, expl: "Les <b>néoruraux</b> sont des urbains qui choisissent de vivre à la campagne (qualité de vie, prix du logement, télétravail) : ils contribuent au <b>renouveau</b> de certains espaces de faible densité." },
  { q: "Quel est un enjeu majeur pour les espaces de faible densité ?", choices: ["le maintien des services publics et l’accès au numérique", "la construction de gratte-ciel", "la lutte contre les embouteillages"], answer: 0, expl: "Dans les espaces peu peuplés, l’enjeu est de garder <b>écoles, médecins, commerces</b> et d’assurer une bonne <b>couverture numérique</b>, pour éviter l’isolement et attirer de nouveaux habitants." },
  { q: "Quel acteur finance des projets d’aménagement en France grâce à des fonds régionaux ?", choices: ["l’ONU", "l’Union européenne", "l’OTAN"], answer: 1, expl: "L’<b>Union européenne</b> finance des projets d’aménagement (routes, numérique, rénovation) grâce à sa politique régionale (fonds FEDER), surtout dans les régions en difficulté. L’OTAN est une alliance militaire." },
  { q: "Que signifie le sigle ZEE ?", answers: ["zone économique exclusive", "une zone économique exclusive"], expl: "La <b>zone économique exclusive</b> s’étend jusqu’à 200 milles marins (environ 370 km) des côtes : l’État y exploite seul les ressources (pêche, pétrole). Grâce à ses outre-mer, la France en a une immense." },
  { type: 'vf', q: "Dans les DROM, le coût de la vie est en général plus faible qu’en métropole.", answer: 1, expl: "<b>Faux</b> : la vie y est en général <b>plus chère</b> (surtout l’alimentation), car beaucoup de produits sont importés. Les DROM connaissent aussi un chômage plus élevé qu’en métropole." },
  { q: "Combien la France compte-t-elle de départements et régions d’outre-mer (DROM) ?", answers: ["5", "cinq"], expl: "Il y a <b>5 DROM</b> : Guadeloupe, Martinique, Guyane, La Réunion et Mayotte. Les autres territoires (Polynésie, Nouvelle-Calédonie…) ont d’autres statuts (COM, statut particulier)." },
  { q: "Combien d’États utilisent l’euro (zone euro) ?", choices: ["une vingtaine", "5", "les 27 États de l’Union européenne"], answer: 0, expl: "La zone euro compte <b>21 États</b> depuis l’entrée de la Bulgarie en 2026 (la Croatie l’avait rejointe en 2023). Plusieurs membres de l’UE gardent leur monnaie, comme la Suède, le Danemark ou la Pologne." },
  { type: 'vf', q: "L’espace Schengen et l’Union européenne ont exactement les mêmes membres.", answer: 1, expl: "<b>Faux</b> : la Suisse et la Norvège sont dans l’espace Schengen sans être dans l’UE, et l’Irlande est dans l’UE sans être dans Schengen. Les deux ensembles ne se superposent pas." },
  { q: "Quel est le principal objectif d’une ligne à grande vitesse (LGV) en matière d’aménagement ?", choices: ["remplacer les routes départementales", "réduire les temps de trajet et mieux relier les métropoles", "limiter le tourisme"], answer: 1, expl: "Une <b>LGV</b> rapproche les grandes villes (Paris-Lyon en 2 heures environ) et renforce leur attractivité. Mais elle peut aussi accentuer l’écart avec les territoires qu’elle traverse sans s’y arrêter." },
  { q: "Quel nom porte l’ensemble des pays et des personnes qui ont le français en partage ?", answers: ["Francophonie", "la Francophonie", "OIF", "Organisation internationale de la Francophonie"], expl: "La <b>Francophonie</b> (et son organisation, l’OIF) réunit des États où le français est parlé : c’est un outil de l’<b>influence</b> culturelle de la France dans le monde." },
  { q: "Après Paris, quelle est la deuxième aire urbaine de France ?", choices: ["Lyon", "Lille", "Bordeaux", "Toulouse"], answer: 0, expl: "<b>Lyon</b> est la deuxième aire d’attraction de France (plus de 2 millions d’habitants), devant Marseille-Aix, Lille, Toulouse et Bordeaux. Paris dépasse 13 millions d’habitants." },
  { q: "Le secteur primaire regroupe :", choices: ["le commerce, la santé et l’éducation", "l’industrie et le bâtiment", "l’agriculture, la pêche et l’exploitation forestière"], answer: 2, expl: "Le secteur <b>primaire</b> exploite directement les ressources naturelles (agriculture, pêche, forêt) ; il emploie moins de 3 % des actifs. Le <b>secondaire</b> = industrie ; le <b>tertiaire</b> = services." }
];
BANK['hgemc/ec4-emc'] = [
  { q: "Un délit, comme un vol, est jugé par :", choices: ["la cour d’assises", "le tribunal correctionnel", "le tribunal de police"], answer: 1, expl: "Les <b>délits</b> (vol, violences, escroquerie) relèvent du <b>tribunal correctionnel</b>. Les crimes vont devant la cour d’assises, les contraventions devant le tribunal de police." },
  { q: "Range les infractions de la moins grave à la plus grave :", choices: ["contravention → délit → crime", "délit → contravention → crime", "crime → délit → contravention"], answer: 0, expl: "La <b>contravention</b> est la moins grave (stationnement interdit), puis le <b>délit</b> (vol), enfin le <b>crime</b> (meurtre), jugé par la cour d’assises." },
  { q: "Quel juge est spécialisé dans les affaires concernant les mineurs ?", answers: ["juge des enfants", "le juge des enfants"], expl: "Le <b>juge des enfants</b> s’occupe des mineurs délinquants mais aussi des enfants en danger. La justice des mineurs privilégie l’<b>éducatif</b> sur le répressif." },
  { type: 'vf', q: "Un conflit entre deux voisins à propos d’une haie relève de la justice pénale.", answer: 1, expl: "<b>Faux</b> : un litige entre particuliers, sans infraction, relève de la justice <b>civile</b>. La justice pénale sanctionne les <b>infractions</b> (contraventions, délits, crimes)." },
  { q: "Faire appel d’un jugement, c’est :", choices: ["demander l’aide d’un avocat", "demander qu’il soit réexaminé par une juridiction supérieure", "refuser d’assister à son procès"], answer: 1, expl: "Le droit de <b>faire appel</b> permet d’obtenir un second jugement devant une <b>cour d’appel</b> : c’est une garantie contre les erreurs judiciaires, au même titre que la présomption d’innocence." },
  { q: "Le préambule de la Constitution de 1946 affirme surtout :", choices: ["le principe de la monarchie constitutionnelle", "des droits sociaux (droit à l’emploi, à la santé, droit syndical, droit de grève)", "la séparation des Églises et de l’État"], answer: 1, expl: "Adopté à la Libération, le <b>préambule de 1946</b> complète la DDHC par des <b>droits économiques et sociaux</b> : droit de grève, droit syndical, protection de la santé, égalité femmes-hommes. Il fait partie de notre bloc de constitutionnalité." },
  { q: "Quelle organisation internationale adopte la Déclaration universelle des droits de l’homme en 1948 ?", answers: ["ONU", "l’ONU", "Organisation des Nations unies", "l’Organisation des Nations unies", "Nations unies"], expl: "La DUDH est adoptée par l’Assemblée générale de l’<b>ONU</b>, créée en 1945. Ne la confonds pas avec la Convention européenne (1950), adoptée par le <b>Conseil de l’Europe</b>." },
  { q: "Dans quelle ville siège la Cour européenne des droits de l’homme ?", answers: ["Strasbourg"], expl: "La Cour européenne des droits de l’homme siège à <b>Strasbourg</b>. Tout citoyen d’un État signataire peut la saisir, après avoir épuisé les recours dans son pays." },
  { type: 'vf', q: "Le droit à la santé et le droit à la Sécurité sociale sont des droits politiques.", answer: 1, expl: "<b>Faux</b> : ce sont des droits <b>sociaux</b>. Les droits <b>politiques</b> concernent la participation à la vie publique : voter, être élu. Les droits <b>civils</b> sont les libertés individuelles (expression, propriété…)." },
  { q: "Lequel de ces devoirs s’impose à tout citoyen français ?", choices: ["respecter la loi et contribuer aux charges publiques par l’impôt", "voter obligatoirement à toutes les élections", "adhérer à un parti politique"], answer: 0, expl: "En France, le vote est un <b>droit</b> et un devoir civique, mais il n’est <b>pas obligatoire</b>. En revanche, respecter la loi et payer l’impôt (article 13 de la DDHC) s’imposent à tous." },
  { q: "L’OTAN est :", choices: ["une agence de l’Union européenne pour l’agriculture", "une alliance militaire dont la France est membre", "un tribunal international"], answer: 1, expl: "L’<b>OTAN</b> (Organisation du traité de l’Atlantique Nord), créée en 1949, est une <b>alliance militaire</b> de défense collective, à laquelle la France participe. Elle a réintégré son commandement intégré en 2009." },
  { q: "Comment appelle-t-on les opérations militaires menées par la France hors de son territoire ?", answers: ["opérations extérieures", "OPEX", "les opérations extérieures", "des opérations extérieures"], expl: "Les <b>opérations extérieures</b> (OPEX) déploient l’armée française à l’étranger, souvent dans un cadre international (ONU, OTAN, UE), pour la sécurité ou le maintien de la paix." },
  { q: "Parmi les gestes qui sauvent, dans quelle position place-t-on une victime inconsciente qui respire ?", choices: ["debout, soutenue par deux personnes", "la position latérale de sécurité (PLS)", "assise contre un mur"], answer: 1, expl: "Une victime <b>inconsciente</b> qui <b>respire</b> est mise en <b>PLS</b> (sur le côté) pour libérer ses voies respiratoires, puis on alerte les secours (15, 18 ou 112)." },
  { q: "Les éco-délégués sont des élèves engagés :", choices: ["pour représenter la classe au conseil de discipline", "pour surveiller la cour de récréation", "pour le développement durable dans leur établissement"], answer: 2, expl: "Les <b>éco-délégués</b> mènent des actions de développement durable (tri, gaspillage, biodiversité) : c’est une forme d’<b>engagement</b> au cœur de l’EMC." },
  { q: "Quel dispositif permet aux jeunes de 16 à 25 ans de s’engager plusieurs mois pour une mission d’intérêt général, avec une indemnité ?", answers: ["service civique", "le service civique"], expl: "Le <b>service civique</b> (créé en 2010) propose des missions de 6 à 12 mois dans des associations ou des services publics, indemnisées, ouvertes à tous les jeunes de 16 à 25 ans (30 ans pour les jeunes en situation de handicap)." },
  { q: "Dans un journal, un éditorial est :", choices: ["une publicité", "une dépêche factuelle d’agence de presse", "un texte d’opinion qui exprime la position du journal"], answer: 2, expl: "L’<b>éditorial</b> exprime le <b>point de vue</b> de la rédaction : c’est une opinion, pas une information neutre. Distinguer information et opinion est un objectif central de l’EMI." },
  { q: "Face à une information choquante partagée sur un réseau social, quel est le premier bon réflexe ?", choices: ["vérifier la source et la croiser avec d’autres médias fiables", "la partager vite pour prévenir ses amis", "la croire si elle a beaucoup de « j’aime »"], answer: 0, expl: "Avant de partager, on <b>vérifie la source</b> (qui publie ? quand ?) et on <b>croise</b> avec d’autres médias. Le nombre de partages ou de « j’aime » ne prouve rien : les infox circulent souvent plus vite que les vraies informations." },
  { type: 'vf', q: "Les algorithmes des réseaux sociaux sélectionnent les contenus selon nos goûts, ce qui peut nous enfermer dans une « bulle de filtres ».", answer: 0, expl: "<b>Vrai</b> : les algorithmes proposent surtout ce qui ressemble à ce que l’on a déjà aimé : on voit de moins en moins d’avis différents. Comprendre ce mécanisme fait partie de l’<b>éducation aux médias</b>." },
  { type: 'vf', q: "Un mineur de 13 ans qui a commis une infraction est jugé par la cour d’assises, comme un adulte.", answer: 1, expl: "<b>Faux</b> : les mineurs relèvent de juridictions <b>spécialisées</b> (juge des enfants, tribunal pour enfants, cour d’assises des mineurs pour les crimes commis après 16 ans) et d’une justice qui privilégie l’éducatif." },
  { q: "Laquelle de ces situations constitue une discrimination punie par la loi ?", choices: ["choisir un candidat plus diplômé pour un poste qui exige ce diplôme", "refuser de louer un logement à quelqu’un qui ne peut pas payer le loyer", "refuser de louer un logement à quelqu’un en raison de son origine"], answer: 2, expl: "Une <b>discrimination</b> est un traitement défavorable fondé sur un <b>critère interdit</b> par la loi (origine, sexe, handicap, religion…). Refuser pour une raison objective (solvabilité, diplôme exigé) n’en est pas une." }
];
BANK['hgemc/hc4-methode'] = [
  { q: "Quel est l’ordre des étapes de l’analyse d’un document ?", choices: ["critiquer → présenter → prélever → expliquer", "présenter → prélever → expliquer → porter un regard critique", "expliquer → prélever → critiquer → présenter"], answer: 1, expl: "On <b>présente</b> d’abord le document (nature, auteur, date), on <b>prélève</b> les informations, on les <b>explique</b> avec ses connaissances, et seulement à la fin on porte un <b>regard critique</b>." },
  { q: "Dans l’analyse d’un document, « prélever » signifie :", choices: ["résumer le document en une phrase", "donner son avis personnel", "relever des informations précises (citations, chiffres)"], answer: 2, expl: "<b>Prélever</b>, c’est extraire des éléments précis du document : <b>citations</b> entre guillemets, <b>chiffres</b>, détails d’une image. Sans ces preuves, l’explication reste vague." },
  { type: 'vf', q: "Quand on cite un extrait de document, on le place entre guillemets.", answer: 0, expl: "<b>Vrai</b> : les <b>guillemets</b> montrent que les mots sont ceux de l’auteur du document, pas les tiens. Indique aussi la ligne si le texte est numéroté." },
  { q: "Document : « Discours de Robert Badinter à l’Assemblée nationale, 17 septembre 1981 ». Quelle est la nature de ce document ? (un mot)", answers: ["discours", "un discours"], expl: "La <b>nature</b> d’un document, c’est son type : ici un <b>discours</b> politique, prononcé devant les députés pour défendre l’abolition de la peine de mort. Ne confonds pas nature (discours) et thème (peine de mort)." },
  { q: "L’introduction d’un développement construit doit contenir :", choices: ["la conclusion du raisonnement", "une liste de toutes les dates du chapitre", "le contexte et la problématique, avec l’annonce du plan"], answer: 2, expl: "L’<b>introduction</b> situe le sujet (<b>contexte</b> : dates, lieux), pose la <b>problématique</b> et annonce le plan. La conclusion, elle, répond à la problématique à la fin." },
  { q: "Quel connecteur logique exprime une conséquence ?", choices: ["cependant", "d’abord", "donc", "par exemple"], answer: 2, expl: "« <b>Donc</b> » (comme « c’est pourquoi », « ainsi ») exprime une <b>conséquence</b>. « Cependant » marque une opposition, « d’abord » une étape, « par exemple » une illustration." },
  { q: "Quel plan convient au sujet « Montrez que le régime de Vichy collabore avec l’Allemagne nazie » ?", choices: ["1) une collaboration politique et économique ; 2) une collaboration policière et la persécution des Juifs (rafle du Vél’ d’Hiv)", "1) la Résistance ; 2) la Libération", "1) les causes de la Première Guerre mondiale ; 2) le traité de Versailles"], answer: 0, expl: "Le plan doit <b>répondre au sujet</b> : montrer les formes de la collaboration. Les deux autres plans sont <b>hors sujet</b> (autre période, ou thème de la Résistance) : c’est l’erreur la plus pénalisée au concours." },
  { type: 'vf', q: "Une source secondaire peut être utile, par exemple un graphique réalisé par un historien à partir d’archives.", answer: 0, expl: "<b>Vrai</b> : une source <b>secondaire</b> (produite après les faits, par un historien) apporte une synthèse et des données construites. Il faut simplement la présenter comme telle (auteur, date de publication)." },
  { q: "Sur un croquis, comment représenter des flux migratoires ?", choices: ["par des flèches (figuré linéaire)", "par un simple point (figuré ponctuel)", "par une plage de couleur (figuré surfacique)"], answer: 0, expl: "Un <b>flux</b> (de personnes, de marchandises) se représente par une <b>flèche</b>, dont l’épaisseur peut indiquer l’importance. Les surfaces servent aux zones, les points aux villes ou aux ports." },
  { q: "Une légende de croquis « organisée » est :", choices: ["classée par couleur, du clair au foncé", "rangée par ordre alphabétique", "classée en parties thématiques avec des titres"], answer: 2, expl: "Une <b>légende organisée</b> est divisée en <b>2 ou 3 parties</b> titrées (par exemple : 1. Des espaces attractifs ; 2. Des espaces en difficulté), qui reprennent souvent le plan du raisonnement." },
  { q: "Comment appelle-t-on l’ensemble des noms de lieux écrits sur un croquis ?", answers: ["nomenclature", "la nomenclature"], expl: "La <b>nomenclature</b> désigne les noms (villes, fleuves, mers, régions) inscrits sur le croquis. Elle doit être lisible, écrite horizontalement si possible, et hiérarchisée." },
  { q: "Pour représenter des densités de population croissantes sur un croquis, on utilise :", choices: ["un dégradé d’une même couleur, du plus clair au plus foncé", "des flèches de plus en plus longues", "des couleurs choisies au hasard"], answer: 0, expl: "Pour une <b>gradation</b> (densités faibles → fortes), on choisit un <b>dégradé</b> d’une même couleur : plus c’est foncé, plus c’est dense. Des couleurs différentes suggéreraient des catégories sans ordre." },
  { type: 'vf', q: "L’orientation d’un croquis s’indique en général par une flèche pointant vers le nord.", answer: 0, expl: "<b>Vrai</b> : une petite flèche marquée « N » indique le <b>nord</b>. Avec le titre, la légende et l’échelle, c’est un élément attendu sur une carte ou un croquis." },
  { q: "Combien d’années séparent l’Hégire (622) de la disparition de l’URSS (1991) ?", answers: ["1369", "1369 ans", "1 369"], expl: "1991 − 622 = <b>1369 ans</b>. Ces deux repères encadrent le programme d’histoire du cycle 4 : ils sont les deux bornes de ta frise de révision." },
  { q: "Sur une frise de 622 à 1991, avec 1 cm pour 50 ans, quelle longueur (en cm) faut-il prévoir ?", answers: ["27,38", "27.38", "27,38 cm", "27.38 cm"], expl: "Durée : 1991 − 622 = 1369 ans. Longueur : 1369 ÷ 50 = <b>27,38 cm</b>. Une frise de révision tient donc sur une feuille A4 posée à l’horizontale (29,7 cm)." },
  { q: "Pour faire comprendre la vie dans les tranchées à des CM2, quelle démarche est la plus adaptée ?", choices: ["partir d’une lettre de poilu et d’une photographie, questionner, puis rédiger une trace écrite courte", "dicter un cours de deux pages sur les causes de la guerre", "faire apprendre par cœur la liste des batailles"], answer: 0, expl: "À l’école, on part d’un <b>document accessible</b> (témoignage, photo), on <b>questionne</b> (qui ? quand ? que voit-on ?), puis on institutionnalise une <b>trace écrite courte</b>. C’est la démarche attendue dans la partie didactique." },
  { q: "Une lettre de soldat de 1916 décrit la vie au front de façon rassurante. Quelle limite dois-tu signaler ?", choices: ["c’est une source secondaire écrite après la guerre", "son auteur n’a pas vécu les événements", "la censure militaire et l’autocensure (ne pas inquiéter sa famille)"], answer: 2, expl: "Les lettres étaient lues par la <b>censure</b> militaire, et les soldats évitaient d’inquiéter leurs proches (<b>autocensure</b>). La source est bien primaire et l’auteur témoin, mais elle ne dit pas tout." },
  { q: "Lors de la présentation d’un document, comment appelle-t-on la personne ou le public à qui il s’adresse ?", answers: ["destinataire", "le destinataire", "les destinataires", "destinataires"], expl: "Le <b>destinataire</b> (un roi, des électeurs, des soldats…) aide à comprendre l’<b>intention</b> de l’auteur : on n’écrit pas de la même façon pour convaincre l’opinion ou pour informer un supérieur." },
  { q: "La paraphrase, à éviter dans l’analyse d’un document, consiste à :", choices: ["citer un passage entre guillemets", "confronter le document à ses connaissances", "répéter le contenu du document avec d’autres mots, sans l’expliquer"], answer: 2, expl: "<b>Paraphraser</b>, c’est redire le document sans rien apporter. Il faut au contraire <b>expliquer</b> : mobiliser ses connaissances pour éclairer le contexte, le sens et la portée du document." },
  { type: 'vf', q: "Pour expliquer un document, on mobilise ses connaissances afin d’éclairer ce qu’il montre et aussi ce qu’il ne dit pas.", answer: 0, expl: "<b>Vrai</b> : l’explication confronte le document aux <b>connaissances</b> : elle précise le contexte, complète ce qui est sous-entendu et signale les <b>silences</b> du document (ce qu’il omet)." }
];
